window.COURSES=[{"id":"w01a","week":1,"part":"a","title":"数据初探：读懂一人一行的队列","summary":"从官方 50,000 人合成队列的字段、分布和随访记录开始，建立描述数据的基本方法。","notebook":"w01a_first_look.ipynb","kind":"concept","sections":[{"title":"1. 确定数据来源与观察单位","paragraphs":["本课精讲直接读取官方 Asset1 的完整合成队列。保存输出为 50,000 行、12 列，每一行对应一名合成人员。官方指数据发布来源；这些记录不包含真实患者，练习结果不能用于临床决策。工程实践中的训练集人数另行计算。","先查看文件路径、形状和前五行。路径确认读取对象，形状检查数据规模，前五行帮助辨认字段和值。只看几条记录无法判断整个队列的分布，后续仍需逐列汇总。"],"code":"df = pd.read_csv(paths.ASSET1)\nprint(df.shape)\ndf.head()","language":"python","codeNote":"摘自单元格 4、6；先运行原笔记本的导入单元格。保存形状为 (50000, 12)。"},{"title":"2. 区分存储类型与统计含义","paragraphs":["df.info() 显示 Age 为小数、diabetes 为整数、smoking_status 为文本。统计分析还要识别连续、二分类和有序分类。糖尿病的 0、1 表示状态；IRSD 的 1 至 5 表示地区社会经济劣势等级，不能按个人收入金额解释。","连续指标必须带单位。BMI 的单位为 kg/m²，SBP 为 mmHg，HbA1c 为百分比。年龄相差 10 的含义是相差 10 岁；IRSD 相差一个等级只说明分组次序发生变化。"],"table":{"headers":["字段","统计类型","读取要点"],"rows":[["Age","连续","基线年龄，岁"],["smoking_status","分类","non、ex、current"],["diabetes","二分类","0 无，1 有"],["IRSD_quintile","有序分类","1 劣势最高，5 劣势最低"],["cvd_event / cvd_time","结局记录","事件状态与观察年数联合解释"]]}},{"title":"3. 同时检查缺失、中心与离散程度","paragraphs":["isna().sum() 按列统计缺失，保存结果中 12 列均为零。完整性只覆盖缺失这一项，单位错误、异常编码和不合理范围仍需检查。","describe() 给出均值、标准差和分位数。完整队列年龄均值 49.71 岁，标准差 12.37 岁；BMI 中位数 28.33，四分位数为 24.92 与 31.73。标准差描述数值围绕均值的分散程度，四分位区间包含中间约一半观测。HbA1c 均值 4.79%、中位数 4.66%，还需结合直方图观察右侧长尾。"],"code":"df.isna().sum()\ncontinuous = [\"Age\", \"BMI\", \"SBP\", \"HbA1c\", \"eGFR\", \"cvd_time\"]\ndf[continuous].describe().T","language":"python","formula":"IQR = 第 75 百分位数 − 第 25 百分位数"},{"title":"4. 用分布图定位边界堆积","paragraphs":["直方图将连续数值分箱，柱高表示落入该区间的人数。分箱太宽会掩盖边界，太窄会突出随机波动。笔记本使用年龄 1 岁、BMI 0.5 单位的分箱，再用精确相等的计数验证边界现象。","保存输出显示年龄恰为 18 岁的有 280 人、90 岁的有 30 人，BMI 恰为 15 的有 197 人。这些堆积与数据生成时的截断相符。处理此类值之前，应核对生成规则或测量范围；直接删除会改变分布。"],"code":"print((df[\"Age\"] == 18).sum())\nprint((df[\"Age\"] == 90).sum())\nprint((df[\"BMI\"] == 15).sum())","language":"python","codeNote":"单元格 24 的三项边界计数；保存结果依次为 280、30、197。"},{"title":"5. 联合读取事件状态与随访时间","paragraphs":["cvd_event=1 表示观察到 CVD 事件，cvd_time 记录从基线到事件的年数。cvd_event=0 表示观察结束前未记录事件，此时 cvd_time 是已知无事件的观察时长。超过这一时点的状态仍未知，这种记录属于右删失。","保存统计中，事件组观察时间中位数为 2.13 年，删失组为 4.90 年。事件出现就结束首次事件分析中的观察，因此不能把事件组较短的观察时间解释为较短随访导致发病。"],"table":{"headers":["源表行号","cvd_time，年","cvd_event","含义"],"rows":[["0","约 2.96","1","约第 2.96 年观察到 CVD 事件"],["1","约 4.41","0","约 4.41 年内未观察到事件，之后未知"]]}},{"title":"6. 写清事件比例的分母","paragraphs":["完整队列观察到 2,009 例 CVD 事件，除以 50,000 得到 4.018%。这个比例描述不同观察时长混合后的记录情况。有人不足五年就结束观察，所以该数值不能直接作为五年累积发病风险。","groupby 可以按糖尿病分组，count 统计人数、sum 统计事件数、mean 计算 0/1 变量的组内比例。每组的分母为该组人数。年龄、血压等差异也可能参与组间关联，描述性比较本身无法建立因果效应。"],"code":"by_diabetes = df.groupby(\"diabetes\")[\"cvd_event\"].agg(\n    人数=\"count\", 事件数=\"sum\", 事件比例=\"mean\"\n)\nby_diabetes","language":"python","formula":"观察事件比例 = 观察到的事件数 ÷ 纳入人数","note":"本课输出使用官方完整队列；后续工程课改用训练集时，分母与结果会随样本改变。"}],"exercises":[{"prompt":"计算 2,009 例事件在 50,000 人中的观察比例，并选择准确解释。","choices":[{"text":"4.018%，表示各自观察期内记录到事件的人所占比例","explanation":"2,009 ÷ 50,000 = 0.04018。随访长度不同，尚未进行固定时间风险估计。"},{"text":"4.018%，表示五年内必然发病的概率","explanation":"早期删失者的五年状态未知，且现有事件标志覆盖各人的整个观察期。"},{"text":"约 4.19%，分母使用删失人数","explanation":"分母应为这次汇总纳入的 50,000 人；删失人数仅为其中一个子集。"}],"correct":0},{"prompt":"解释一条 cvd_time=4.41、cvd_event=0 的记录。","choices":[{"text":"已观察约 4.41 年且未记录事件，之后状态未知","explanation":"删失保留已知观察时间，不提供整个生命期或完整五年的状态。"},{"text":"此人已证实五年无事件","explanation":"观察只到约 4.41 年，缺少剩余时间的信息。"},{"text":"此人可从分析中删除","explanation":"这段无事件观察对后续生存分析提供信息。"}],"correct":0},{"prompt":"为 IRSD_quintile 选择合适的数据字典说明。","choices":[{"text":"地区社会经济劣势的有序类别，需保留等级方向","explanation":"编码 1 至 5 具有顺序，不能据此推定个人收入或等级间的等距关系。"},{"text":"连续收入，5 表示收入是 1 的五倍","explanation":"数值是类别编码，没有这种倍数意义。"},{"text":"只需记录 int64","explanation":"存储类型不足以说明统计含义、编码方向与分析用途。"}],"correct":0}],"takeaways":["每行的观察单位、字段含义和单位要先于计算确认。","分布、缺失与边界值需要结合数值表和图检查。","事件比例使用明确分母；删失记录必须保留观察时间。"]},{"id":"w01b","week":1,"part":"b","title":"数据校验：来源、标识与字段字典","summary":"用工程流程保留来源、检查患者标识并划分数据，将每个字段整理成可复核的数据字典。","notebook":"w01b_data_literacy.ipynb","kind":"practice","sections":[{"title":"1. 显式选择官方或演示模式","paragraphs":["工程篇通过配置文件读取数据。official 模式对应官方 50,000 人合成队列，来源和完整性记录保存在 data/raw/manifest.json。demo 模式使用另外生成的 5,000 人离线夹具，输出必须标明演示来源。缺少官方文件时，应完成官方下载或明确选择演示模式。","原始文件保持不变，清洗结果与分析输出放到独立目录。本课设置 outputs/notebooks_official，使笔记本结果与原始文件分开。更换模式后重新核对打印的来源、队列人数及划分人数，不能继续沿用另一模式的统计结果。"],"code":"MODE = \"official\"\ncfg = load_config(ROOT / \"configs\" / f\"{MODE}.json\")\ncfg[\"output_dir\"] = f\"outputs/notebooks_{MODE}\"\nprint(provenance_label(cfg))\ndf, splits = prepare(cfg)","language":"python","codeNote":"摘自单元格 1；ROOT、load_config、provenance_label、prepare 由同格前半部分导入。"},{"title":"2. 核对一人一行及连接标识","paragraphs":["工程读取函数给官方 12 个字段添加 source_row_index 与 Patient_ID，因此显示结果包含 14 列。source_row_index 保存源表行号，Patient_ID 供跨表连接；首行的两项值分别为 0 与 269。添加辅助列不会改变官方原始 CSV。","Patient_ID.is_unique 的保存结果为 True。唯一性保证当前表中每个患者标识只出现一次，却不能保证全部字段正确。标识值和行号都不能输入预测模型：它们主要记录数据组织方式，缺乏所需的基线医学含义。"],"code":"display(df.head())\ndisplay(pd.DataFrame({\n    \"dtype\": df.dtypes.astype(str),\n    \"missing\": df.isna().sum()\n}))\nprint(df.Patient_ID.is_unique)","language":"python"},{"title":"3. 将字段字典写到可执行的细度","paragraphs":["每个字段至少记录中文含义、单位、允许编码、获取时点和模型用途。Age 记录基线年龄；HbA1c 的百分比不能与其他单位直接混用；smoking_status 的 non、ex、current 要保留原有含义。遇到新编码，应先审查来源再修改规则。","用途随研究任务变化。SBP 在本项目的 CVD 模型中可作基线特征，在第 3 周线性回归中用作结局。diabetes 在第 4 周也是结局，且该课排除与诊断密切相关的 HbA1c。字段在基线获得，并不意味着每个模型都应纳入。"],"table":{"headers":["字段","单位或编码","时点与用途"],"rows":[["Age","岁","基线候选特征"],["BMI","kg/m²","基线候选特征"],["HbA1c","%","基线检验；第 4 周排除"],["SBP","mmHg","基线测量；第 3 周结局"],["cvd_event","0 / 1","随访结局，禁止作为基线输入"],["cvd_time","年","事件或删失时间，禁止作为基线输入"],["Patient_ID","整数标识","连接使用，禁止作为预测输入"]]}},{"title":"4. 按患者划分并限制探索范围","paragraphs":["prepare 生成固定的患者级划分。保存输出为队列 50,000 人、训练集 35,000 人、验证集 7,500 人；其余 7,500 人为测试集，本课不创建测试 DataFrame。相同患者不能同时出现在不同集合中。","查看全表字段与少量记录用于结构校验。后续用于决定模型形式、变换或特征的探索限于训练集；验证集用于评价和学习，测试集留到方案冻结后。概念篇中的完整队列演示和工程篇中的建模流程因此需要分别标注。"],"code":"train = select_split(df, splits, \"train\")\nvalid = select_split(df, splits, \"valid\")\nprint(len(df), len(train), len(valid))","language":"python","codeNote":"单元格 1 保存输出为 50000 35000 7500；本段不读取测试集。"},{"title":"5. 审查五年结局的可观察性","paragraphs":["audit_clean 将字段、缺失、事件和观察时长汇总为审查结果。官方完整队列的事件数为 2,009，观察事件比例为 0.04018。变量名特意保留 not_5y_risk，提醒该比例的统计口径。","其中 27,542 人在五年前未发生事件就结束观察；20,517 人的观察时间超过五年。这两个计数使用不同条件，不能相加后直接当作事件与非事件的二分类表。最短观察时间约为 0.002427 年，在两位小数显示中会接近 0.00，显示舍入应与真实零值区分。"],"code":"from primecvd.data import audit_clean\ndisplay(pd.Series(audit_clean(df, cfg[\"horizon_years\"])))","language":"python","note":"审查的是完整队列结构与观察支持；模型拟合和模型选择仍按划分边界进行。"},{"title":"6. 留下可以复核的交付物","paragraphs":["完成全部字段的字典后，另附三项记录：所用模式与来源文件，完整队列和各分析集合人数，以及校验发现和处理理由。例行校验包括合法类别、二元变量的 0/1 编码、有限的正观察时间和患者标识唯一性。","再选一条实际记录写明其基线信息和观察结果。描述 cvd_event=0 时必须带上观察时长。保留源字段名可让文字解释直接回到数据，不用凭列的显示顺序猜测含义。"]}],"exercises":[{"prompt":"选择能在缺少官方文件时保持来源准确的操作。","choices":[{"text":"明确切换到 demo 并将产物标注为独立演示数据","explanation":"两种模式对应不同数据。显式选择与来源标签使结果可以追溯。"},{"text":"用 demo 结果继续标注官方 50,000 人","explanation":"演示夹具有独立生成过程和不同规模，这会伪造数据来源。"},{"text":"只修改表格中的人数","explanation":"修改标签无法改变实际数据和计算分母。"}],"correct":0},{"prompt":"说明 Patient_ID 唯一且没有缺失时，在建模中的处理方式。","choices":[{"text":"保留用于连接与划分，从预测特征中排除","explanation":"数据管理标识的完整性和预测变量的科学适用性需要分别判断。"},{"text":"按连续数值输入模型","explanation":"标识大小不能解释为生理暴露的增加。"},{"text":"从所有表中永久删除","explanation":"删除会破坏患者级连接、核对和划分。"}],"correct":0},{"prompt":"解释审查结果中五年前删失的 27,542 人。","choices":[{"text":"各自观察结束前未记录事件，五年状态未完整观察","explanation":"这些人有可用的无事件观察时段，但无法全部编码为五年阴性。"},{"text":"五年内已知没有 CVD 的 27,542 人","explanation":"删失发生在五年前，剩余时间没有结局记录。"},{"text":"35,000 人训练集中的删失人数","explanation":"该审查调用使用 df，保存分母为完整队列 50,000 人。"}],"correct":0}],"takeaways":["官方队列与独立演示夹具分别记录来源和人数。","患者标识服务于连接和划分，结局与标识不进入基线预测特征。","字段字典同时说明单位、编码、获取时点和具体模型用途。"]},{"id":"w02a","week":2,"part":"a","title":"描述性分析：基线表、分层与人年率","summary":"在官方完整队列中构建基线表，按 IRSD 分层，并将事件数和观察时长转换为人年发病率。","notebook":"w02a_descriptive.ipynb","kind":"concept","sections":[{"title":"1. 统一基线表的汇总格式","paragraphs":["本课使用完整的官方 50,000 人合成队列。基线表展示纳入人群及各组的特征，连续变量可报告均值和标准差，偏态变量同时关注中位数与四分位数，类别变量报告人数和组内百分比。每个百分比都需对应明确的列分母。","对 0/1 变量，sum 得到取值为 1 的人数，mean 得到比例。保存示例为年龄 49.7（12.4）岁、HbA1c 中位数 4.7%［4.2，5.1］、糖尿病 3,717 人（7.4%）。区间两端为第 25 和第 75 百分位数。"],"code":"def mean_sd(x):\n    return f\"{x.mean():.1f} ({x.std():.1f})\"\n\ndef median_iqr(x):\n    q1, q2, q3 = x.quantile([0.25, 0.50, 0.75])\n    return f\"{q2:.1f} [{q1:.1f}, {q3:.1f}]\"\n\ndef n_pct(x):\n    return f\"{int(x.sum()):,} ({x.mean() * 100:.1f}%)\"","language":"python","codeNote":"摘自单元格 3；二元计数函数适用于 0/1 或布尔变量。"},{"title":"2. 先解释差异大小，再看检验结果","paragraphs":["按后续是否观察到 CVD 事件分组，无事件组 47,991 人，事件组 2,009 人。事件组平均年龄 63.0 岁，无事件组 49.2 岁，差约 13.8 岁；收缩压分别为 136.0 与 122.8 mmHg，差约 13.2 mmHg。","源表演示 Welch t 检验、Mann–Whitney U 检验和卡方检验。保存的多数 P 值小于 0.001，但 P 值不能表示差异大小，也不能证明临床重要性。分组依据发生于随访期，表内关联还受年龄等因素影响，不能直接归因给某项暴露。"],"table":{"headers":["指标","无 CVD 事件","有 CVD 事件"],"rows":[["人数","47,991","2,009"],["年龄，均值（SD），岁","49.2（12.1）","63.0（11.6）"],["SBP，均值（SD），mmHg","122.8（15.9）","136.0（16.5）"],["基线糖尿病，n（%）","2,518（5.2）","1,199（59.7）"]]}},{"title":"3. 按 IRSD 展开分层结果","paragraphs":["IRSD 是地区社会经济劣势指标，1 组劣势最高、5 组最低。groupby 后使用 agg 可在同一张表内同时给出人数、均值和比例。各等级在本合成队列中的人数不相等，计算比例时仍使用各自分母。","1 组与 5 组的当前吸烟比例为 15.4% 和 5.1%，前者约为后者的 3 倍；平均 BMI 为 29.5 和 27.1。CVD 事件比例依次为 4.3%、4.4%、4.3%、3.7%、3.4%，总体随劣势降低而下降，但相邻组并非逐级下降。均龄相近也不足以独立证明因果或中介机制。"],"code":"irsd = df.groupby(\"IRSD_quintile\").agg(\n    人数=(\"Age\", \"size\"),\n    平均年龄=(\"Age\", \"mean\"),\n    现在吸烟_百分比=(\"smoking_status\", lambda s: (s == \"current\").mean() * 100),\n    CVD事件_百分比=(\"cvd_event\", lambda s: s.mean() * 100)\n)","language":"python","codeNote":"精简自单元格 9；保留原分组与汇总方式。"},{"title":"4. 用总观察时间计算人年发病率","paragraphs":["每个人从基线到事件或删失的时间相加，得到总人年。2 人各被观察 3 年，共贡献 6 人年。事件数除以总人年后再乘 1,000，可报告每千人年的事件发生率。量纲中保留时间，因此不能将其直接当作某个固定年限的概率。","糖尿病组观察到 1,199 个事件、约 14,889 人年，发病率为每千人年 80.5；非糖尿病组为 810 个事件、约 224,886 人年，发病率为每千人年 3.6。这里的人年显示值已四舍五入，精确计算应使用未舍入的时间总和。"],"formula":"人年 = Σ每人的观察年数；发病率 = 事件数 ÷ 人年 × 1,000","code":"out = df.groupby(\"diabetes\", observed=True).agg(\n    人数=(\"cvd_event\", \"size\"),\n    事件数=(\"cvd_event\", \"sum\"),\n    人年=(\"cvd_time\", \"sum\")\n)\nout[\"每千人年发病率\"] = out[\"事件数\"] / out[\"人年\"] * 1000","language":"python","codeNote":"将单元格 14 的分组率计算展开；这只是未调整的描述性分组率。"},{"title":"5. 给估计值配上相应的区间","paragraphs":["比例图使用 Wilson 95% 置信区间；均值图使用均值加减 1.96 个标准误；人年率使用精确 Poisson 区间。三种区间分别对应不同估计量。事件数越少，率的相对不确定性通常越大，不能只按总人数判断精度。","18–39 岁组有 10,854 人、51 个事件，每千人年率为 1.0，95% 区间 0.7–1.3；70 岁以上组有 2,567 人、566 个事件，率为 51.7，区间 47.5–56.1。后者的绝对区间较宽，相对率本身的幅度却较小。区间依赖相应统计模型与数据条件。"],"formula":"率下限 = χ²₀.₀₂₅,₂ₖ ÷ (2 × 人年)；率上限 = χ²₀.₉₇₅,₂ₖ₊₂ ÷ (2 × 人年)","note":"公式中的 k 为事件数；换成每千人年需乘 1,000。k=0 时下限按 0 处理，原演示分组均有事件。"},{"title":"6. 让坐标和导出保留统计含义","paragraphs":["年龄分组使用左闭右开区间，因此 40 岁进入 40–49 组。线性纵轴突出率的绝对差，对数纵轴突出倍数差。首个年龄组覆盖 18 至不足 40 岁，末组开放到 70 岁以上，不能把五个组的等距横坐标直接解释为统一的每十岁变化。","点估计图可截取纵轴范围，但应明示尺度并显示置信区间；条形长度表达数值时应从零起。最后将基线表、IRSD 表和年龄率表导出到 outputs/tables，保留完整队列、单位和区间方法说明。"],"code":"df[\"age_group\"] = pd.cut(\n    df[\"Age\"], bins=[18, 40, 50, 60, 70, np.inf],\n    labels=[\"18–39\", \"40–49\", \"50–59\", \"60–69\", \"70+\"],\n    right=False\n)\npaths.save_table(irsd, \"02_irsd_stratified\")","language":"python","codeNote":"摘自单元格 16、21。"}],"exercises":[{"prompt":"用约 14,889 人年和 1,199 个事件计算糖尿病组的每千人年发病率。","choices":[{"text":"约 80.5 例/千人年","explanation":"1,199 ÷ 14,889 × 1,000 ≈ 80.5。人年已舍入，结果与保存输出的一位小数一致。"},{"text":"约 32.3% 的五年风险","explanation":"1,199 除以 3,717 得到观察事件比例，既未使用人年，也未处理五年前删失。"},{"text":"80.5%","explanation":"乘 1,000 得到每千人年单位，不能直接改写成百分比。"}],"correct":0},{"prompt":"比较 18–39 岁与 70 岁以上组的率区间，选择正确解读。","choices":[{"text":"70 岁以上组绝对区间较宽，18–39 岁组相对不确定性较大","explanation":"0.7–1.3 围绕约 1.0 的比例幅度较大；47.5–56.1 围绕 51.7 的相对幅度较小。"},{"text":"10,854 人组人数更多，所以任何尺度上都更精确","explanation":"率的精度还取决于事件数与观察时间，年轻组只有 51 个事件。"},{"text":"95% 区间表示 95% 人的个体发病率","explanation":"这是总体率估计的不确定性区间，不描述个体值的分布范围。"}],"correct":0},{"prompt":"解释 IRSD 五组的 CVD 事件比例 4.3%、4.4%、4.3%、3.7%、3.4%。","choices":[{"text":"总体下降且存在相邻组波动，只能先作为描述性关联","explanation":"显示的比例支持总体梯度，不能推出严格单调规律或因果机制。"},{"text":"每升一级都严格降低","explanation":"1 组到 2 组的显示值上升，2 组与 3 组也有局部差异。"},{"text":"该序列已完成年龄和其他危险因素调整","explanation":"这些值来自分组均值，没有拟合调整模型。"}],"correct":0}],"takeaways":["组内百分比、人年率和固定时间风险使用不同分母与时间含义。","同时报告差异大小和不确定性，避免只依赖 P 值。","分组边界、坐标尺度和输出路径都影响结果能否正确复核。"]},{"id":"w02b","week":2,"part":"b","title":"训练集探索：基线表与三类图","summary":"在固定训练集中完成分布探索，用基线表、直方图、箱线图和类别比例检查数据。","notebook":"w02b_eda.ipynb","kind":"practice","sections":[{"title":"1. 固定本课的分析人群","paragraphs":["本课沿用官方患者级划分：完整队列 50,000 人，训练集 35,000 人，验证集 7,500 人。用于建模前分布探索的对象为 train。第 2 周 a 的表基于完整队列，本课的表基于训练集，人数和摘要出现小幅差异属于样本变化。","若切换到 demo，应从配置重新准备数据，重新标注来源与样本量。本课引用的保存输出全部来自 official。测试集不参与查看图后再选变量、分组边界或变换方案的过程。"],"code":"df, splits = prepare(cfg)\ntrain = select_split(df, splits, \"train\")\nvalid = select_split(df, splits, \"valid\")\nprint(len(df), len(train), len(valid))","language":"python","codeNote":"摘自单元格 1；先运行同格中的配置和模块导入。"},{"title":"2. 将训练集基线表读到每个分母","paragraphs":["training_summary(train) 对连续变量给出均值、标准差、中位数和分位区间，对类别变量给出频数和百分比。连续变量行中的 n 表示参与汇总的观测数，类别行中的 n 表示该类别的人数，读取时应结合 variable 字段。","保存表中糖尿病 2,600 人，占训练集 7.43%；CKD 230 人，房颤 253 人。当前吸烟 3,570 人、已戒烟 5,832 人、从不吸烟 25,598 人，合计 35,000。人数较少的亚组在后续分析中尤其需要报告估计的不确定性。"],"code":"from primecvd.pipeline import training_summary\ndisplay(training_summary(train))","language":"python","table":{"headers":["训练集类别","人数","占 35,000 人比例"],"rows":[["diabetes=1","2,600","7.43%"],["CKD=1","230","0.66%"],["AF=1","253","0.72%"],["smoking_status=current","3,570","10.20%"],["smoking_status=ex","5,832","16.66%"],["smoking_status=non","25,598","73.14%"]]}},{"title":"3. 直方图检查年龄分布","paragraphs":["源代码将训练集年龄切为 30 个箱，横轴为岁，纵轴为人数。图上注明 n=35,000，可防止读者将其与完整队列图混用。比较峰的位置、左右尾部和边界附近的堆积，再与基线表中的分位数相互核对。","分箱数量会改变视觉细节，但原始样本保持不变。改变分箱后若一个异常形状消失，应回到数值计数核实。图注只写当前训练样本的观察，不把合成数据的分布推广为真实地区的人群分布。"],"code":"fig, ax = plt.subplots(figsize=pp.size(pp.SINGLE, 58))\nax.hist(train.Age, bins=30, color=pp.NEUTRAL, lw=0)\nax.set(xlabel=\"年龄（岁）\", ylabel=\"人数\")\nplt.show()","language":"python","codeNote":"摘自单元格 4；完整笔记本还在图上标注训练样本量。"},{"title":"4. 箱线图对照糖尿病组的 BMI","paragraphs":["箱体上下边缘表示第 25 与第 75 百分位数，中间线表示中位数；默认须线按四分位距规则延伸。两组使用相同纵轴，便于比较中心和分散程度。组人数应同时标注，避免把 32,400 人与 2,600 人的证据强度视作完全相同。","源图设置 showfliers=False，隐藏须线外的绘图标记以减少重叠。这个选项不会从 train 删除记录，箱线图也因此不能单独展示全部极端值。完整范围仍需从数值摘要或额外图中检查。图中的组间差异不等同于糖尿病造成的 BMI 变化。"],"code":"groups = [train.loc[train.diabetes.eq(k), \"BMI\"] for k in (0, 1)]\nax.boxplot(\n    groups, tick_labels=[\"无糖尿病\", \"糖尿病\"],\n    showfliers=False\n)","language":"python","codeNote":"精简自单元格 5；绘图前创建新的 fig、ax。"},{"title":"5. 用行归一化读取分类构成","paragraphs":["crosstab 先统计糖尿病与吸烟的交叉人数。normalize=\"index\" 将每行除以该行总人数，因此无糖尿病行以 32,400 为分母，糖尿病行以 2,600 为分母。每行比例未舍入时之和为 1。","保存结果中，两组当前吸烟比例分别为 0.102 与 0.099，均约一成。从不吸烟比例都显示为 0.731。三个小数位的相同只说明显示精度下相同，无法据此断言真实概率相等，也不足以判断吸烟与糖尿病的因果关系。"],"code":"pd.crosstab(\n    train.diabetes, train.smoking_status, normalize=\"index\"\n).round(3)","language":"python","formula":"某组内类别比例 = 该组该类别人数 ÷ 该组总人数","table":{"headers":["基线糖尿病","current","ex","non"],"rows":[["0","0.102","0.166","0.731"],["1","0.099","0.170","0.731"]]}},{"title":"6. 完成三张图与文字验收","paragraphs":["练习交付年龄直方图、按糖尿病分组的 BMI 箱线图，以及吸烟类别条形图。类别条形图使用人数或百分比均可，但纵轴标签必须一致，比例分母固定为训练集人数，条形轴从零起。","每张图配两句解释：第一句给出具体观察和样本，第二句说明解释范围。吸烟图可写当前吸烟者为 3,570/35,000，即 10.20%；随后注明这一合成训练样本的比例不能作为真实人群患病或暴露水平。基线表以描述为主，无需逐行机械添加显著性检验。"],"code":"counts = train[\"smoking_status\"].value_counts().reindex([\"non\", \"ex\", \"current\"])\nax = (counts / len(train) * 100).plot.bar()\nax.set_ylabel(\"占训练集人数的百分比（%）\")\nax.set_ylim(bottom=0)","language":"python","codeNote":"根据单元格 6 的独立练习编写；与单元格 3 的训练集类别计数核对。"}],"exercises":[{"prompt":"计算糖尿病组 2,600 人占训练集的比例。","choices":[{"text":"2,600 ÷ 35,000 ≈ 7.43%","explanation":"本课基线表对象为训练集，使用 35,000 为分母。"},{"text":"2,600 ÷ 50,000 = 5.20%","explanation":"分子取自训练集，分母却取自完整队列，口径不一致。"},{"text":"2,600 ÷ 7,500 ≈ 34.67%","explanation":"7,500 是验证集人数，不能与训练集分子混用。"}],"correct":0},{"prompt":"解释箱线图中 showfliers=False 的作用。","choices":[{"text":"隐藏须线外的点标记，数据仍保留","explanation":"该参数改变显示方式，不执行过滤或删除。"},{"text":"从训练数据删除所有异常观测","explanation":"绘图参数没有修改数据框。"},{"text":"证明数据中没有极端观测","explanation":"隐藏后的图无法证明极端值不存在，需要另行核对。"}],"correct":0},{"prompt":"解释糖尿病行中当前吸烟比例 0.099 的分母。","choices":[{"text":"糖尿病组的 2,600 人","explanation":"normalize=\"index\" 按行归一化，每个糖尿病状态使用自己的组人数。"},{"text":"全训练集的 35,000 人","explanation":"这适用于全体类别比例，不适用于这里的行内比例。"},{"text":"当前吸烟的 3,570 人","explanation":"以吸烟类别总人数为分母对应另一种条件比例。"}],"correct":0}],"takeaways":["训练集探索与完整队列教学分别标注数据范围。","图形简化不得被误读为数据删除或没有极端值。","组内比例、全体比例与显示舍入需要逐项说明。"]},{"id":"w03","week":3,"part":"","title":"线性回归：单位、调整与预测误差","summary":"用训练集的年龄、BMI 和吸烟状态拟合收缩压，逐项解释系数、残差和验证误差。","notebook":"w03_linear_regression.ipynb","kind":"practice","sections":[{"title":"1. 把目标和分析集合固定下来","paragraphs":["本课结局为基线收缩压 SBP，单位 mmHg。模型在官方队列的 35,000 人训练集中拟合，用 7,500 人验证集评价，测试集保持封存。输入仅包含年龄、BMI 和吸烟状态，所有解释都以这组变量及其函数形式为条件。","线性回归给出输入特征对应的平均 SBP。实际 SBP 与拟合值之间的差称为残差。最小二乘法选择一组系数，使训练样本的残差平方和最小；平方会使较大的偏差受到更高权重。"],"formula":"ŷ = β₀ + β年龄 × (Age/10) + βBMI × (BMI/5) + β戒烟 × I(ex) + β吸烟 × I(current)；残差 e = y − ŷ"},{"title":"2. 展开设计矩阵与参考类别","paragraphs":["design_basics 将年龄除以 10，将 BMI 除以 5。这是预先规定的单位换算，年龄系数直接对应 10 岁差异，BMI 系数对应 5 kg/m² 差异。这里未从完整队列学习均值或标准差。","吸烟建立 ex 与 current 两列指示变量，从不吸烟 non 作为参考。已戒烟时两列为 1、0，当前吸烟时为 0、1，从不吸烟时为 0、0。截距对应年龄和 BMI 都为零且从不吸烟的数学基准，超出本队列的实际测量范围。"],"code":"from primecvd.basics import design_basics\nX = design_basics(train)\nmodel = sm.OLS(train.SBP, X).fit(cov_type=\"HC3\")","language":"python","codeNote":"摘自单元格 3；设计矩阵实现见 primecvd/basics.py，单元格 4 说明单位缩放。"},{"title":"3. 给每个系数补齐完整解释","paragraphs":["年龄系数为 4.037905：在模型中保持 BMI 与吸烟类别相同时，年龄高 10 岁对应平均 SBP 高约 4.04 mmHg。相同线性模型下，20 岁差异对应 2×4.037905，约 8.08 mmHg。","BMI 系数为 5.350511，表示保持年龄与吸烟类别相同时，BMI 高 5 kg/m² 对应平均 SBP 高约 5.35 mmHg。当前吸烟相对从不吸烟的调整后平均差约为 4.07 mmHg。统计调整本身不能保证消除全部混杂，解释限于条件关联。"],"table":{"headers":["模型项","系数，mmHg","95% 区间"],"rows":[["intercept","72.269653","71.217106 至 73.322200"],["Age_per10","4.037905","3.916673 至 4.159138"],["BMI_per5","5.350511","5.201181 至 5.499842"],["smoking_ex","1.829893","1.421194 至 2.238591"],["smoking_current","4.065956","3.565997 至 4.565914"]]}},{"title":"4. 读取 HC3 区间的适用范围","paragraphs":["系数表中的区间反映估计不确定性。年龄每 10 岁系数的 95% 区间为 3.916673 至 4.159138 mmHg，可与点估计一并报告。该区间围绕平均差的参数，不表示个体 SBP 会落在这个范围。","HC3 调整系数标准误，使推断对残差方差随特征变化更稳健。它不会自动修正遗漏变量、错误的线性函数形式或数据错误。读取区间之前仍需检查模型设定和数据来源，并将统计精度与实际预测误差分开。"],"code":"interval = model.conf_int()\npd.DataFrame({\n    \"coefficient\": model.params,\n    \"CI_low\": interval[0],\n    \"CI_high\": interval[1]\n})","language":"python","codeNote":"展开自单元格 3 的系数输出。"},{"title":"5. 用残差图检查模型形式","paragraphs":["横轴绘制拟合 SBP，纵轴绘制训练残差。残差为正表示实际值高于拟合值，为负表示实际值低于拟合值。零线提供参照。检查残差中心是否随拟合值弯曲，以及垂直散布是否逐渐扩张或收缩。","弯曲提示当前线性形式可能遗漏结构；漏斗状散布提示方差可能变化。单张图不能证明所有假设成立。原笔记本允许探索年龄二次项，但应在训练流程内评估，不能依据最终测试结果反复决定保留方式。"],"code":"ax.scatter(\n    model.fittedvalues, model.resid,\n    s=2, alpha=0.15, color=pp.NEUTRAL, lw=0\n)\npp.ref_line(ax, 0, axis=\"y\")\nax.set(xlabel=\"拟合的收缩压（mmHg）\", ylabel=\"残差（mmHg）\")","language":"python","codeNote":"摘自单元格 5；先创建 fig、ax。小点与透明度用于减少 35,000 个点重叠。"},{"title":"6. 在验证集中计算 RMSE","paragraphs":["验证集使用与训练集完全相同的设计矩阵规则。先预测每人的 SBP，逐人计算实际值减预测值，再平方、取平均并开平方，得到 RMSE。开平方使结果回到 mmHg 单位，便于与收缩压尺度比较。","保存的验证 RMSE 为 14.1968108 mmHg，约 14.20 mmHg。它汇总 7,500 人的预测偏差，不能解释为每个人都偏差 14.20，也不能保证误差都在这个范围内。训练残差诊断和独立验证误差各自提供不同信息。"],"formula":"RMSE = √[Σ(yᵢ − ŷᵢ)² ÷ n验证]","code":"pred = model.predict(design_basics(valid))\nrmse = np.sqrt(np.mean((valid.SBP - pred) ** 2))\nprint(float(rmse))","language":"python","codeNote":"单元格 5 的验证计算；n验证 = 7,500。"}],"exercises":[{"prompt":"在 BMI 和吸烟相同的模型条件下，计算年龄高 20 岁对应的平均 SBP 差。","choices":[{"text":"约高 8.08 mmHg","explanation":"Age_per10 高 2 个单位，差为 2×4.037905=8.07581 mmHg。"},{"text":"约高 80.76 mmHg","explanation":"年龄系数已经按每 10 岁缩放，不能再按每岁乘 20。"},{"text":"每个个体都会高 8.08 mmHg","explanation":"系数描述条件平均差，个体值还有残差和未建模因素。"}],"correct":0},{"prompt":"解释当前吸烟系数 4.065956 的参照和单位。","choices":[{"text":"同年龄和 BMI 下，当前吸烟比从不吸烟的平均 SBP 高约 4.07 mmHg","explanation":"参考类别 non 的两个指示变量都为 0，current 系数直接比较该类别与参考。"},{"text":"当前吸烟比已戒烟高约 4.07 mmHg","explanation":"当前吸烟与已戒烟的比较需要相减两项系数。"},{"text":"吸烟导致个人血压上升 4.07%","explanation":"系数单位为 mmHg，当前模型估计也没有建立因果效应。"}],"correct":0},{"prompt":"选择验证 RMSE=14.20 mmHg 的正确说明。","choices":[{"text":"验证集平方误差平均后开平方的汇总指标","explanation":"该值使用 7,500 名验证人员的预测误差，单位与 SBP 相同。"},{"text":"95% 人的误差不超过 14.20 mmHg","explanation":"RMSE 本身不提供这个覆盖比例。"},{"text":"HC3 已使验证误差全部为零","explanation":"HC3 用于标准误估计，不消除残差或预测误差。"}],"correct":0}],"takeaways":["系数解释同时写明单位、参考类别和模型中固定的其他变量。","HC3 处理标准误问题，仍需检查函数形式与残差。","验证 RMSE 汇总预测误差，不能代替个体预测区间。"]},{"id":"w04","week":4,"part":"","title":"Logistic 回归：优势比、概率与阈值","summary":"用基线糖尿病分类练习 logit 与 OR，并结合概率指标和混淆矩阵评价模型。","notebook":"w04_logistic_regression.ipynb","kind":"practice","sections":[{"title":"1. 明确这次分类的结局时点","paragraphs":["本课预测已有的基线糖尿病状态 diabetes，结局为 0 或 1。输入使用年龄、BMI、吸烟，主动排除与糖尿病诊断密切相关的 HbA1c。任务属于横断面状态分类，不能据此宣称预测未来糖尿病发生。","模型在官方合成队列的 35,000 人训练集拟合，在 7,500 人验证集评价，测试集保持封存。保存的验证集糖尿病人数为 557，占 7.4267%；这个比例与训练集或完整队列的比例分别记录。"],"code":"X = design_basics(train)\nmodel = sm.GLM(\n    train.diabetes, X, family=sm.families.Binomial()\n).fit()\nprobability = model.predict(design_basics(valid)).to_numpy()","language":"python","codeNote":"摘自单元格 3；沿用第 3 周的单位缩放和 non 参考类别。"},{"title":"2. 从线性预测值变换为概率","paragraphs":["Logistic 模型先计算线性预测值 η=Xβ，再用 1/(1+exp(−η)) 得到 0 到 1 之间的概率 p。p/(1−p) 称为优势，logit(p) 是优势的自然对数。p=0.20 时优势为 0.20/0.80=0.25。","同样的线性预测值增量在不同起始概率处会产生不同的概率增量。η=0 对应 p=0.5，η 为负对应 p 小于 0.5。源笔记本前五名验证人员的预测概率约为 0.0297、0.0525、0.0165、0.0192、0.1357。这些数值尚未转成分类标签。"],"formula":"logit(p) = ln[p/(1−p)] = Xβ；p = 1/(1+e⁻η)","note":"0.20 等数值用于手算教学；前五个预测概率来自单元格 3 的保存输出。"},{"title":"3. 通过指数函数解释优势比","paragraphs":["系数取指数后得到 OR。同年龄和吸烟条件下，BMI 每增加 5 kg/m² 的 OR 为 1.709233；同 BMI 和吸烟条件下，年龄每增加 10 岁的 OR 为 1.784998。含义是模型中的糖尿病优势分别乘以这些数值，不能直接当作增加相同比例的概率。","以手算示例说明：若起始概率为 0.20，优势为 0.25；OR=2 后优势变为 0.50，转回概率为 0.50/1.50，约 0.333。已戒烟和当前吸烟相对 non 的区间均包含 1，报告时同时保留点估计及区间，不据此宣布两组完全无差异。"],"formula":"新优势 = 原优势 × OR；新概率 = 新优势 ÷ (1+新优势)","table":{"headers":["模型项","OR","95% 区间"],"rows":[["年龄，每 10 岁","1.784998","1.723923 至 1.848236"],["BMI，每 5 kg/m²","1.709233","1.638972 至 1.782507"],["已戒烟，相对从不吸烟","1.007048","0.901121 至 1.125426"],["当前吸烟，相对从不吸烟","0.967424","0.841790 至 1.111809"]]}},{"title":"4. 用阈值生成标签并读取混淆矩阵","paragraphs":["源笔记本预先固定阈值 0.5：概率大于等于 0.5 记为预测 1，其余记为预测 0。这个阈值仅作教学示例。概率 0.20 在此阈值下会得到标签 0，但该人的模型概率仍为 0.20。","验证集混淆矩阵按实际类别为行、预测类别为列排列。真阳性 4，假阴性 553，假阳性 3，真阴性 6,940。模型只报出 7 个阳性。灵敏度为 4/557，约 0.72%，说明该阈值漏掉了大多数实际阳性。"],"table":{"headers":["验证集，n=7,500","预测 0","预测 1"],"rows":[["实际 0","6,940","3"],["实际 1","553","4"]]},"code":"confusion_matrix(\n    valid.diabetes, probability >= 0.5, labels=[0, 1]\n)","language":"python","codeNote":"单元格 4；阈值只改变标签及混淆矩阵，不会重新拟合模型。"},{"title":"5. 准确率与类别不平衡一起报告","paragraphs":["此阈值的准确率为 (6,940+4)/7,500，约 92.59%。如果把所有人都判为 0，准确率也有 6,943/7,500，约 92.57%。两项数值均由保存矩阵直接计算，较高准确率主要受多数类别影响。","阳性预测值为 4/7，约 57.14%，但仅有 7 个预测阳性，不能脱离计数解释稳定性。降低阈值通常增加检出，同时增加假阳性，阈值选择需要明确漏诊与误报的代价。本练习没有提供临床最优阈值，测试集也不能用于反复挑选阈值。"],"formula":"灵敏度 = TP/(TP+FN)；阳性预测值 = TP/(TP+FP)；准确率 = (TP+TN)/n"},{"title":"6. 分开评价排序和概率误差","paragraphs":["保存的验证 AUROC 为 0.7369，衡量阳性相对阴性的排序能力。AUPRC 字段实际调用 average_precision_score，值为 0.2219，属于平均精确率 AP 汇总；比较时同时给出验证阳性比例 0.07427 作为参考。它与简单梯形积分的 PR 面积定义可能有差异。","Brier 分数为 0.06379，是每人预测概率与 0/1 结局差的平方均值，越小通常表示概率误差更低，但单一分数不能证明校准良好。CVD 结局存在早期删失，不能照搬这套完整二分类评价，把所有 cvd_event=0 都当作已知五年阴性。"],"formula":"Brier = Σ(pᵢ−yᵢ)² ÷ n","table":{"headers":["验证指标","保存值","解释要点"],"rows":[["AUROC","0.7368767","概率排序"],["AP，原输出标记 AUPRC","0.2218670","随阈值变化的精确率与召回率汇总"],["糖尿病比例","0.0742667","557 / 7,500"],["Brier","0.0637876","平均平方概率误差"]]}}],"exercises":[{"prompt":"从起始概率 0.20 出发，将优势乘以 OR=2，计算新概率。","choices":[{"text":"约 0.333","explanation":"原优势为 0.20/0.80=0.25，乘 2 得 0.50，再算 0.50/(1+0.50)=1/3。"},{"text":"0.40","explanation":"概率直接翻倍混淆了概率和优势。"},{"text":"2.20","explanation":"OR 为比值，不能当作概率的加法增量。"}],"correct":0},{"prompt":"根据 TP=4、FN=553 计算阈值 0.5 的灵敏度。","choices":[{"text":"4/557，约 0.72%","explanation":"灵敏度的分母为全部实际阳性，557=4+553。"},{"text":"4/7，约 57.14%","explanation":"这个分母是全部预测阳性，对应阳性预测值。"},{"text":"6,944/7,500，约 92.59%","explanation":"这个式子对应准确率，受多数阴性类别影响很大。"}],"correct":0},{"prompt":"解释概率 0.20 在阈值 0.5 下生成的分类标签 0。","choices":[{"text":"预测概率保留为 0.20，标签由阈值规则给出","explanation":"概率与标签是不同输出层次；改变阈值能改变标签，但原概率保持不变。"},{"text":"模型认为此人发病概率为零","explanation":"标签 0 只表示概率低于当前阈值。"},{"text":"模型已证明此人未来五年没有糖尿病","explanation":"模型目标是已有基线状态，也没有作出这种确定性判断。"}],"correct":0}],"takeaways":["先确定基线状态分类的目标，避免改写为未来发病预测。","OR 作用于优势，概率经阈值才转为标签。","类别不平衡时同时看计数、检出能力、排序和概率误差。"]},{"id":"w05a","week":5,"part":"a","title":"删失、风险集与 Kaplan–Meier 曲线","summary":"用官方完整队列理解观察时间、右删失和 KM 连乘，并正确读取五年累积风险。","notebook":"w05a_km_basics.ipynb","kind":"concept","sections":[{"title":"把结局保留为时间与状态","paragraphs":["本篇使用 Data Asset 1 的全部 50,000 人讲解生存分析。每行提供 cvd_time 和 cvd_event：前者是事件发生或观察结束的时间，单位为年；后者记录观察期内是否出现 CVD 事件。精讲的全队列描述与工程篇的训练集分析要分别标注。","右删失表示观察结束后结局未知。一个人随访两年仍无事件，只能确认前两年无事件；第五年状态仍未知。把这行删掉会丢失两年无事件的信息，把它归为五年阴性又会添加没有观察到的信息。KM 在这个人仍被观察时使用其贡献，删失后将其移出风险集。"],"formula":"观察时间 T = min(事件时间, 删失时间)；事件标志 δ = 1 表示观察到事件"},{"title":"逐个事件时刻连乘","paragraphs":["风险集包含某个事件时刻到来前仍在观察、尚未发生事件的人。设第 j 个事件时刻有 nⱼ 人处于风险集，发生 dⱼ 个事件，那么跨过该时刻的条件生存比例为 1−dⱼ/nⱼ。把所有事件时刻的比例依次相乘，得到 S(t)。累积风险为 1−S(t)。","用三人的教学例子演算：甲在一年发生事件，乙在两年删失，丙在三年发生事件。一年前风险集为三人，S(1)=2/3；乙在两年离开观察，S(2)仍为2/3；三年前风险集只剩丙，S(3)=0。删失自身不使曲线下降，它改变后续事件的分母。最后一步只有一人支持，估计非常脆弱。"],"formula":"Ŝ(t) = ∏(tⱼ≤t) (1 − dⱼ/nⱼ)；R̂(t) = 1 − Ŝ(t)","note":"三人例子用于手算算法，不代表官方队列的事件模式。"},{"title":"分别计算事件比例与五年风险","paragraphs":["官方队列整个观察期记录 2,009 个事件，其中 1,941 个发生在五年内，68 个在五年之后。2,009/50,000=4.018% 是观察期事件比例；1,941/50,000=3.882% 使用固定分母，仍未处理五年前删失。KM 五年风险为 4.0464%，来自随时间更新的风险集。三个数接近时也要保留各自定义。","下面直接用 lifelines 拟合。predict(5)返回五年生存概率，取补数后得到五年累积风险。保存输出按两位小数显示百分比，因此 4.0464% 显示为4.05%；图中按一位小数标为4.0%。"],"code":"kmf = KaplanMeierFitter()\nkmf.fit(df[\"cvd_time\"], event_observed=df[\"cvd_event\"])\nfor t in [1, 3, 5]:\n    print(t, 1 - kmf.predict(t))","language":"python","codeNote":"改写自单元格4；df 为前文已读取的官方完整队列。","table":{"headers":["时间","保存输出中的累积风险"],"rows":[["1年","0.98%"],["3年","2.69%"],["5年","4.05%"]]}},{"title":"结合风险人数读曲线尾部","paragraphs":["原图同时展示累积风险、95%置信区间与风险人数表。第五年仍在风险集的有20,517人，第六年降至1,003人。越到尾部，少量事件对曲线的影响越大，区间通常也更宽。曲线在六年处截断，是按实际随访支持限制展示范围。","累积风险从零向上绘制，便于观察几个百分点的变化。图上某一点的置信区间描述该时点总体风险估计的不确定性，不能读作某个人的预测区间。读取两组差异时，还要比较各组剩余人数，避免只凭尾部高度下结论。"],"table":{"headers":["随访年数","全队列风险人数"],"rows":[["0","50,000"],["1","49,510"],["3","48,636"],["5","20,517"],["6","1,003"]]},"figure":{"file":"w05a_km_basics_cell5.png","alt":"官方完整50,000人队列的KM累积风险，阴影为95%区间，下方列出风险人数。","caption":"官方完整50,000人队列的KM累积风险，阴影为95%区间，下方列出风险人数。 源 Notebook 保存输出，第 6 个单元格。"}},{"title":"分组曲线与 log-rank 比较","paragraphs":["按 diabetes 分组后分别拟合 KM，得到每组随时间变化的描述性风险。log-rank 在各事件时刻比较实际事件数与共同危险过程下的期望事件数，再汇总差异。保存结果为卡方9723.3、P<0.001；IRSD五组比较的P值为0.0003。","P值描述数据与相同生存曲线假设的相容程度，不能替代差异大小。糖尿病组与其他组的年龄、血压等分布不同，未调整曲线不能证明糖尿病造成全部差异。KM还依赖合理的删失假设；这些结果来自合成教育数据，仅用于学习统计方法。"],"code":"dm = df[df[\"diabetes\"] == 1]\nno_dm = df[df[\"diabetes\"] == 0]\nresult = logrank_test(dm[\"cvd_time\"], no_dm[\"cvd_time\"],\n                      dm[\"cvd_event\"], no_dm[\"cvd_event\"])\nprint(result.test_statistic, result.p_value)","language":"python","codeNote":"依据单元格10；本比较没有调整其他基线特征。","figure":{"file":"w05a_km_basics_cell8.png","alt":"官方完整队列按糖尿病分组的KM累积风险，含风险人数和非糖尿病组纵轴放大图。","caption":"官方完整队列按糖尿病分组的KM累积风险，含风险人数和非糖尿病组纵轴放大图。 源 Notebook 保存输出，第 9 个单元格。"}}],"exercises":[{"prompt":"计算三人例子中两年删失刚发生后的生存概率。","choices":[{"text":"1/3","explanation":"将删失当成事件会错误减少生存概率。"},{"text":"2/3","explanation":"正确。一年的事件使生存概率变为2/3，两年的删失只改变后续风险集。"},{"text":"1","explanation":"一年时已经发生过一个事件，前面的下降必须保留。"}],"correct":1},{"prompt":"选择官方完整队列五年 KM 风险对应的数值。","choices":[{"text":"4.0464%","explanation":"正确。它使用随事件和删失变化的风险集计算五年累积风险。"},{"text":"4.018%","explanation":"这是整个观察期的2,009个事件除以50,000人，包含五年后事件。"},{"text":"3.882%","explanation":"这是五年内1,941个事件除以50,000人，尚未处理早期删失。"}],"correct":0},{"prompt":"解释第六年曲线尾部区间变宽的主要依据。","choices":[{"text":"纵轴使用百分比","explanation":"单位转换不会改变相对不确定性。"},{"text":"log-rank 的P值很小","explanation":"分组检验P值不能解释全队列尾部的随访支持。"},{"text":"风险集仅剩约1,000人","explanation":"正确。剩余观察人数减少后，单个事件的影响增加，尾部估计更不稳定。"}],"correct":2}],"takeaways":["删失保留已观察期间的信息，删失后的结局保持未知。","KM 用每个事件时刻的风险集作分母，累积风险等于1−S(t)。","报告曲线差异时同时给出时间、样本口径、风险人数与不确定性。"]},{"id":"w05b","week":5,"part":"b","title":"在训练集实现 KM 与删失核对","summary":"用固定患者划分和项目 KM 接口检查五年前删失、估计五年风险并记录分析口径。","notebook":"w05b_survival_and_censoring.ipynb","kind":"practice","sections":[{"title":"先固定数据来源与分析人群","paragraphs":["工程篇通过 official 配置读取官方数据，再按患者划分训练、验证和最终测试。保存输出是队列50,000人、训练35,000人、验证7,500人。本篇的描述和KM拟合使用训练集，后文百分比的分母随之改变；不能把训练集数字标成全队列结果。","prepare 返回队列及划分表，select_split 按已记录的患者划分取子集。官方文件的下载来源与哈希保存在 manifest 中。demo 用于离线练习和测试，是独立生成的演示样本；切换模式后要更新图表来源、人数与结果，不能沿用官方标签。本篇没有创建最终test数据框。"],"code":"MODE = \"official\"\ncfg = load_config(ROOT / \"configs\" / f\"{MODE}.json\")\ncfg[\"output_dir\"] = f\"outputs/notebooks_{MODE}\"\nprint(provenance_label(cfg))\ndf, splits = prepare(cfg)\ntrain = select_split(df, splits, \"train\")\nvalid = select_split(df, splits, \"valid\")","language":"python","codeNote":"节选单元格1；保留配置、来源标签与患者划分三项检查。"},{"title":"用时间窗识别未知状态","paragraphs":["配置将预测时间窗设为五年。筛选 cvd_event=0 且 cvd_time<5 的记录，得到训练集中五年前删失的19,275人。这个人数来自35,000人的训练集。它衡量五年状态未知的人数，不能直接解释为五年内无事件人数。","保存输出显示训练集共有1,406个观察到的事件，33,594个删失；事件时间最大约5.91年。因此训练集总事件数也包含五年后的事件。分开检查事件人数、事件时间范围与早期删失，能够在计算指标之前发现分母或标签错误。"],"code":"h = cfg[\"horizon_years\"]\nearly = train.cvd_event.eq(0) & train.cvd_time.lt(h)\nprint(int(early.sum()))\ndisplay(train.groupby(\"cvd_event\").cvd_time.agg(\n    [\"count\", \"min\", \"median\", \"max\"]))","language":"python","codeNote":"依据单元格3；本数据没有五年时刻的并列边界问题，复用代码时仍应写明<或≤的约定。","table":{"headers":["训练集状态","人数","观察时间中位数"],"rows":[["cvd_event=0","33,594","4.902383年"],["cvd_event=1","1,406","2.164291年"]]}},{"title":"手算后再检查实现","paragraphs":["先复现三人的时间线：一年事件、两年删失、三年事件。每到事件时刻，先列出仍被观察且尚未发生事件的人；风险集依次为3人和1人。两年删失发生时，生存概率不跳变，但此人不再进入三年的分母。","项目的 KaplanMeier.fit 先汇总相同时间的记录，统计每个时刻的事件数与风险人数，再累乘条件生存比例。读取某时点采用右连续阶梯值，包含该时点已经发生的事件。这个顺序在存在并列事件时间的资料中尤其需要固定。"],"formula":"Ŝ(1)=1−1/3=2/3；Ŝ(2)=2/3；Ŝ(3)=(2/3)×(1−1/1)=0","note":"手算的最后一个风险集只有一人，不能据此作稳定的总体风险推断。实现细节可继续阅读 primecvd/metrics.py。"},{"title":"复现训练集风险与区间","paragraphs":["项目接口用两列结局拟合KM，再通过 risk_ci(5)读取五年风险及点态95%区间。训练集保存结果为4.0383%，区间3.8307%至4.2569%。观察期事件比例为4.0171%，来自1,406/35,000。两者数值相近，各自保留原始名称。","绘图时以事件时间为横轴、1−survival为纵轴，使用post阶梯连接。risk_ci 使用Greenwood方差和log-log变换构建区间，再转换到累积风险尺度。区间描述这一时点总体风险估计的不确定性，不覆盖整条曲线，也不衡量预测模型的性能。"],"code":"from primecvd.metrics import KaplanMeier\nkm = KaplanMeier.fit(train.cvd_time, train.cvd_event)\nprint(train.cvd_event.mean())\nprint(km.risk_ci(h))","language":"python","codeNote":"节选单元格4；保存输出为0.0401714286和(0.0403831008, 0.0383074138, 0.0425687498)。"},{"title":"分组分析与验收记录","paragraphs":["完成总体核对后，按基线diabetes分组，分别传入本组观察时间和事件标志。每组均从自己的风险集计算曲线，并记录各时间点的人数。分组后事件稀少或随访较短的组，其尾部证据通常较弱。","提交时写明official模式、35,000人训练集、五年时间窗、KM风险与区间，并附一句对两年删失记录的解释。KM依赖删失机制方面的假设；如果失访与未来事件密切相关，普通KM可能产生偏差。超出实际随访支持的时间不应继续外推。本项目的合成数据练习不能直接支持临床使用。"],"code":"for value, group in train.groupby(\"diabetes\"):\n    fitted = KaplanMeier.fit(group.cvd_time, group.cvd_event)\n    print(value, len(group), fitted.risk_ci(h))","language":"python","codeNote":"依据单元格6独立练习扩展；这里只提供操作步骤，不预先填入未保存的分组结果。"}],"exercises":[{"prompt":"解释随访两年、cvd_event=0的记录对五年预测评价的含义。","choices":[{"text":"第五年已知无事件","explanation":"观察只到两年，没有覆盖完整五年。"},{"text":"前两年无事件，五年状态未知","explanation":"正确。保留两年观察信息，之后的结局由删失方法处理。"},{"text":"记录不能用于生存分析","explanation":"删失记录在结束观察前仍贡献风险集信息。"}],"correct":1},{"prompt":"为保存结果4.0383%选择完整的报告标签。","choices":[{"text":"官方训练集35,000人的五年KM累积风险","explanation":"正确。数据来源、人群、时间窗和估计方法均与保存输出一致。"},{"text":"官方全队列50,000人的事件比例","explanation":"人群和统计量都变了；完整队列KM五年风险约4.0464%。"},{"text":"演示数据的五年预测准确率","explanation":"来源标签错误，KM总体风险也不属于预测准确率。"}],"correct":0},{"prompt":"判断3.8307%至4.2569%区间应如何解释。","choices":[{"text":"每个人的五年风险都落在这个范围","explanation":"这是总体KM风险的点态区间，不能当作个人预测区间。"},{"text":"模型的C指数置信区间","explanation":"本节未拟合预测模型，区间也没有在C指数尺度上。"},{"text":"训练集五年KM风险估计的点态95%区间","explanation":"正确。区间对应固定五年时点，不能扩大解释为整条曲线的同时置信带。"}],"correct":2}],"takeaways":["工程结果必须连同数据模式、患者划分和分母记录。","训练集中19,275人五年前删失，他们的五年状态未知。","训练集KM五年风险为4.0383%，点态区间与模型性能区间含义不同。"]},{"id":"w06a","week":6,"part":"a","title":"Cox 回归的危险比、调整与预测","summary":"用完整队列学习 Cox 解释、数值检查与 PH 诊断，再区分教学测试演示和工程最终测试。","notebook":"w06a_cox_regression.ipynb","kind":"concept","sections":[{"title":"从瞬时危险理解 HR","paragraphs":["本篇主要用官方完整50,000人队列拟合lifelines模型。Cox将某时点的瞬时危险写成基线危险乘以特征的指数函数。对于特征相差Δx的两人，在其他特征相同时，危险比HR=exp(βΔx)。比例风险假设要求这个比值不随时间改变。","HR按危险比解释。HR=1.5表示模型条件下瞬时危险为1.5倍；五年累积风险还取决于基线危险及其他特征。连续变量的单位决定HR的含义：年龄除以10后，一个单位对应十岁；BMI除以5后，一个单位对应5 kg/m²。"],"formula":"h(t|x)=h₀(t)×exp(xβ)；HR(Δx)=exp(βΔx)"},{"title":"先核验数值收敛","paragraphs":["糖尿病单变量模型的默认拟合曾在保存输出中给出HR≈0。项目记录这是强效应下迭代步长导致的数值发散，调用没有直接抛出错误。默认步长改为0.5后，HR为22.186，95%区间20.292至24.258，与原队列糖尿病组较高的事件率方向一致。","遇到异常结果时，先核对编码、单位、描述统计、优化警告和软件设置，再讨论统计解释。P值显示为0.0通常是数值显示或极小尾概率的结果，报告使用P<0.001。项目说明修正后的拟合已与R survival::coxph核对。"],"code":"FIT_OPTIONS = {\"step_size\": 0.5}\ndata_dm = df[[\"diabetes\", \"cvd_time\", \"cvd_event\"]]\ncox_dm = CoxPHFitter().fit(\n    data_dm, duration_col=\"cvd_time\", event_col=\"cvd_event\",\n    fit_options=FIT_OPTIONS)","language":"python","codeNote":"节选单元格5；默认失败示例位于单元格3，不能将其HR≈0当作研究发现。"},{"title":"编码后读取条件危险比","paragraphs":["make_design将年龄、BMI、收缩压和eGFR分别按10、5、10、10单位缩放，HbA1c按一个百分点解释。吸烟以从不吸烟为参照，IRSD以第5组为参照，其余水平建立0/1指示列。多变量模型同时纳入全部指定列。","森林图用点表示HR，横线表示95%区间，竖线标出HR=1。对数横轴让0.5与2相对1对称。年龄每十岁的调整HR为1.96，糖尿病为5.35；CKD区间0.59至1.25包含1，表示这份模型和数据对其条件关联仍有较大不确定性。"],"table":{"headers":["变量与单位","粗HR","调整HR及95%区间"],"rows":[["年龄每10岁","2.50","1.96（1.88–2.04）"],["糖尿病","22.19","5.35（4.58–6.25）"],["CKD","4.88","0.86（0.59–1.25）"],["当前吸烟，相对从不吸烟","1.45","1.58（1.38–1.81）"]]},"figure":{"file":"cox-hazard-ratios.png","alt":"十四项协变量的粗危险比与调整危险比及百分之九十五区间，对数横轴","caption":"官方完整合成队列 n = 50,000。根据 w06a 单元格 10、12 保存表中两位小数结果重绘，HR 标为危险比；横线为 95% 区间。"}},{"title":"区分模型调整与因果解释","paragraphs":["粗HR与调整HR的变化反映纳入其他变量后的条件比较，不能把差值直接当成某因素的因果贡献。糖尿病HR从22.19降至5.35，与年龄、血压、HbA1c等信息被同时纳入有关；CKD和eGFR的信息重叠，也会影响条件估计。","原教程用已知合成结构演示IRSD经吸烟、BMI等路径关联CVD。IRSD第1组相对第5组的HR，只调整年龄时为1.29，全部调整后为1.00。加入中介会改变目标比较，但这两个Cox系数不能单凭列名便认定为已识别的总因果效应和直接因果效应；真实因果分析仍需要识别假设与相应方法。"],"note":"此处保留原教程的教学比较，避免把合成数据中的条件关联推广为临床或公共卫生因果结论。"},{"title":"诊断比例风险假设","paragraphs":["Schoenfeld残差比较事件发生者的特征与同一时刻风险集的危险加权平均特征。若残差随时间呈系统性变化，恒定HR的假设需要进一步检查。本篇调用lifelines的proportional_hazard_test，使用rank时间变换。","保存表中HbA1c的P=0.042，其余13列均大于0.05。一次略低于阈值的结果应结合多重检验、残差趋势与实质大小理解；P>0.05也不能证明假设成立。工程篇w06b只输出探索性残差，不能把本篇的检验覆盖到所有工程模型。"],"code":"ph = proportional_hazard_test(\n    cph, model_data, time_transform=\"rank\")\ndisplay(ph.summary[[\"test_statistic\", \"p\"]])","language":"python","codeNote":"依据单元格21；对应完整队列的lifelines多变量拟合。"},{"title":"分别记录排序验证与绝对风险","paragraphs":["完整建模数据的C指数为0.876。本篇随后另以随机种子2026进行约70%/30%的教学划分，实际使用了教学测试部分，保存训练C=0.877、测试C=0.873。这个演示已查看测试结果；工程流水线的固定最终测试集仍有独立锁定规则。两套划分不可合并描述。","原文两组输入的五年预测分别为1.4%和69.2%，用于演示predict_survival_function输出。它们由全队列模型给出，不能作为真实个人的医疗建议。C指数评价可比较人员对的排序，绝对概率是否准确还需校准分析；训练与测试C接近，也不能单独证明所有方面均可泛化。"],"code":"rng = np.random.default_rng(2026)\nis_train = rng.random(len(df)) < 0.7\ncph_train = CoxPHFitter().fit(\n    model_data[is_train], duration_col=\"cvd_time\",\n    event_col=\"cvd_event\", fit_options=FIT_OPTIONS)\ntest = model_data[~is_train]\nrisk_score = cph_train.predict_partial_hazard(test)\nc_test = concordance_index(test[\"cvd_time\"],\n                           -risk_score, test[\"cvd_event\"])","language":"python","codeNote":"节选单元格26。lifelines此接口按较长生存方向解释分数，故对危险分数取负；不可把符号直接套到其他C指数接口。"}],"exercises":[{"prompt":"把年龄每十岁的HR=1.96换算成年龄相差二十岁时的HR，保持其他特征相同。","choices":[{"text":"2.96","explanation":"HR在对数尺度上相加，在原尺度上按单位差取幂。"},{"text":"约3.84","explanation":"正确。二十岁对应两个单位，HR=1.96²≈3.84；仍是瞬时危险的倍数。"},{"text":"五年风险增加96个百分点","explanation":"危险比不能直接转换为累积风险的百分点变化。"}],"correct":1},{"prompt":"为本篇测试结果选择准确的记录。","choices":[{"text":"教学划分已评估测试C=0.873，与工程最终测试流程分开记录","explanation":"正确。本篇单元格26确实使用约30%的教学测试部分。"},{"text":"所有notebook从未使用任何测试数据","explanation":"本篇有明确的测试评估输出，这种表述掩盖已发生的查看。"},{"text":"0.873为固定15%工程最终测试结果","explanation":"本篇使用种子2026的约70/30演示，工程固定划分使用另一套配置。"}],"correct":0},{"prompt":"解释IRSD加入中介变量后HR下降到约1的证据范围。","choices":[{"text":"证明IRSD没有任何因果影响","explanation":"调整中介可能改变所估计的比较，条件关联接近1不能排除总影响。"},{"text":"证明全调整系数已识别真实直接因果效应","explanation":"这种解释还需要额外的因果识别假设与相应估计方法。"},{"text":"说明该模型的条件关联随调整变量集合而变化","explanation":"正确。应先明确预测或因果目标，再决定变量集合，并限制结论范围。"}],"correct":2}],"takeaways":["HR是危险比，解释必须包含变量单位、参照组与调整条件。","检查数值收敛、描述统计和残差，再解释模型输出。","w06a的教学测试已被评估，需与工程最终测试集分开报告。"]},{"id":"w06b","week":6,"part":"b","title":"训练 Cox 模型并生成五年绝对风险","summary":"通过项目 CoxModel 接口理解部分似然、临床单位、基线累积危险与验证集预测。","notebook":"w06b_cox_model.ipynb","kind":"practice","sections":[{"title":"建立可审查的输入范围","paragraphs":["工程模型使用官方训练集35,000人拟合，在7,500人验证集上生成预测。先预先指定Age、BMI、SBP、diabetes、smoking_status五个字段，暂不使用完整十字段模型。Patient_ID、cvd_time和cvd_event均不能充当预测变量；后两列只用于生存结局。","CoxModel中的编码器在训练集学习数值缺失的中位数、均值和标准差；验证时复用这些参数。吸烟以non为参照，年龄每10岁、BMI每5单位、收缩压每10 mmHg解释。记录字段集后才能比较模型，避免将不同调整集得到的HR混在一起。"],"code":"features = [\"Age\", \"BMI\", \"SBP\", \"diabetes\", \"smoking_status\"]\nmodel = CoxModel(features, alpha=0.0).fit(train)\ndisplay(model.coefficient_table())\nprint(model.diagnostics)","language":"python","codeNote":"节选单元格3；alpha=0表示普通Cox。编码器规则来自primecvd/features.py。"},{"title":"理解部分似然的分母","paragraphs":["在每个事件时刻，模型比较实际发生事件者的相对危险与当时整个风险集的相对危险总和。某个人的线性得分xβ越大，exp(xβ)越大，其在这一时刻成为事件者的相对权重越高。将各时刻的贡献相乘得到部分似然，再求使它最大的系数。","基线危险在同一时刻的比值中约去，所以先求系数不需要指定h₀(t)的函数形状。删失者在退出观察前仍进入分母。工程实现调用statsmodels的部分似然，采用Breslow处理并列事件时刻；给出的简式对应无并列事件情形。"],"formula":"L(β)=∏(i为事件者) exp(xᵢβ) / Σ(j∈R(Tᵢ)) exp(xⱼβ)","note":"R(Tᵢ)是事件发生前的风险集。数据有并列时刻时，需按实现约定处理。"},{"title":"同时检查系数与优化状态","paragraphs":["保存输出中Age_per10的log_HR为0.716443，取指数得到HR=2.047。糖尿病HR为12.188；它与精讲全模型的5.35不同，原因包括调整字段集合和拟合样本不同，不能只归因于软件差异。","优化记录显示35,000人、1,406个事件、35次迭代，最大绝对梯度约1.19×10⁻⁸。先确认优化结果再读取HR。普通Cox的系数区间来自给定模型的信息矩阵，转换回指定单位；它没有涵盖变量筛选的不确定性，也不属于模型性能区间。"],"table":{"headers":["项","HR","95%区间"],"rows":[["年龄每10岁","2.0471","1.9526–2.1463"],["BMI每5 kg/m²","1.1302","1.0689–1.1951"],["SBP每10 mmHg","1.1007","1.0612–1.1417"],["糖尿病","12.1877","10.8505–13.6898"]]}},{"title":"从基线危险计算绝对风险","paragraphs":["系数确定相对危险后，还需要从训练集事件时刻和风险集估计基线累积危险H₀(t)。代入五年后，先得到累积危险，再通过指数变换得到生存概率，最后取补数。只报告exp(xβ)无法给出五年概率。","用纯数学例子演算：若参照人的五年风险是10%，其生存概率为0.90；HR=1.5的人在比例风险条件下，五年风险为1−0.90¹·⁵≈14.62%。增加约4.62个百分点。实际代码还要考虑线性得分的中心化，模型接口已将基线估计与预测保持一致。"],"formula":"R(5|x)=1−exp[−H₀(5)×exp(xβ)]；同一基线下R₁=1−(1−R₀)ᴴᴿ","code":"p = model.predict_risk(valid, cfg[\"horizon_years\"])\nprint(bool(np.all((p >= 0) & (p <= 1))))","language":"python","codeNote":"节选单元格4，保存检查结果为True。10%和HR=1.5仅是公式演算参数。"},{"title":"保留诊断的适用范围","paragraphs":["model.schoenfeld_residuals(train)返回每个事件时刻的探索性残差。将某变量残差与时间绘图，观察长期趋势，可提示恒定HR假设的疑点。当前工程接口没有完成正式全局PH检验，单独打印几行残差也不能宣布假设成立。","练习扩展到完整预先指定字段时，仍只在训练和验证范围比较，并保留字段集、单位、优化记录及预测时间窗。区分度、校准与删失加权误差在第八周共同评价。合成数据输出只用于方法训练；不能将某个输入字段的改动解释为真实治疗效果。"],"code":"residuals = model.schoenfeld_residuals(train)\ndisplay(residuals.head())","language":"python","codeNote":"节选单元格6；数据行来自事件者，输出用途为探索性诊断。"}],"exercises":[{"prompt":"选择部分似然中某次事件的正确比较范围。","choices":[{"text":"当时仍在观察且尚未发生事件的风险集","explanation":"正确。实际事件者与该时刻所有处于风险集的人比较。"},{"text":"只与最终发生事件的人比较","explanation":"删失者退出前也贡献风险集分母，不能提前排除。"},{"text":"每次都与全队列50,000人比较","explanation":"风险集随事件和删失变化；本篇拟合人群也只有训练集35,000人。"}],"correct":0},{"prompt":"参照五年风险为10%、HR=1.5时，计算同一基线下的新五年风险。","choices":[{"text":"60%","explanation":"把HR增幅误加成百分点会造成数量级错误。"},{"text":"约14.62%","explanation":"正确。先取参照生存概率0.90，再计算1−0.90¹·⁵。"},{"text":"一定等于15%","explanation":"直接乘1.5只是一种近似；比例风险模型的精确关系在生存概率尺度上。"}],"correct":1},{"prompt":"解释本篇糖尿病HR=12.188与精讲全模型HR=5.35的比较条件。","choices":[{"text":"差异证明其中一个软件计算错误","explanation":"必须先统一样本和字段，再评价实现差异。"},{"text":"二者都等于糖尿病组的五年风险","explanation":"HR是条件危险比，数值也不在概率尺度上。"},{"text":"拟合样本和调整字段均不同，应分别报告","explanation":"正确。本篇只用训练集及五个字段；精讲主模型用完整队列与更完整字段。"}],"correct":2}],"takeaways":["部分似然利用事件时刻的风险集估计系数。","绝对风险需要训练集基线累积危险与个体线性得分共同确定。","比较HR前先统一变量单位、参照组、调整字段和拟合人群。"]},{"id":"w07","week":7,"part":"","title":"岭惩罚与训练集内交叉验证","summary":"将预处理、Cox 拟合与删失加权评价全部放进训练折，并按预定规则选择惩罚强度。","notebook":"w07_penalization_and_cv.ipynb","kind":"practice","sections":[{"title":"从系数大小理解 L2 惩罚","paragraphs":["普通Cox选择使部分似然尽可能大的系数。岭惩罚再对系数平方和收费，使极大的系数更难出现。alpha控制这项约束的强度；alpha=0恢复普通Cox。收缩可能降低估计方差，也可能引入偏差，性能改善需由数据验证。","本项目把负对数部分似然除以训练人数n，再加alpha×β平方和的一半。其他软件可能使用不同的损失缩放，因此不能把这里的0.001直接当作另一软件相同数值的惩罚力度。这里实现纯L2收缩，没有实现L1变量筛选。"],"formula":"目标函数 J(β)=−ℓ部分(β)/n + (alpha/2)×Σβⱼ²","note":"目标函数见primecvd/survival.py；本篇候选alpha预先固定为0、0.001、0.01。"},{"title":"在每个训练折重估预处理","paragraphs":["同样大小的系数，在年龄、BMI或0/1指示变量上未必代表同样的变化。工程编码器先按规定单位转换，再用当前训练折的均值和标准差标准化，让L2惩罚作用在可比较的尺度。缺失值中位数也只从这一折学习。","若先用全部50,000人计算均值、标准差或中位数，验证和测试分布就提前进入了建模流程。即使没有使用结局，这也破坏了对新数据的独立模拟。每次执行CoxModel(...).fit(fold_train)都会重新创建并拟合编码器，随后只对fold_valid做变换。"],"formula":"zⱼ=(xⱼ按预定单位缩放−训练折均值ⱼ)/训练折标准差ⱼ","note":"不要把预处理后得到的全队列矩阵直接交给交叉验证。患者划分和折内拟合要贯穿同一条流程。"},{"title":"运行训练集内部三折","paragraphs":["官方训练集包含35,000人。StratifiedKFold按事件状态分层，把它分为三折；每次用两折拟合，在剩余一折评价。分层仅用于使各折事件数量较均衡，事件状态不会进入预测特征。三个候选alpha使用同一组划分，便于公平比较。","每折重新估计编码器、系数和基线累积危险。Brier评价所用删失分布同样从fold_train估计，再对fold_valid的五年概率误差加权。外部的7,500人验证集与最终测试集均不参与这个自动alpha选择过程。"],"code":"folds = list(StratifiedKFold(\n    n_splits=cfg[\"cv_folds\"], shuffle=True,\n    random_state=cfg[\"seed\"] + 2\n).split(train, train.cvd_event))\nrows = []\nfor alpha in cfg[\"ridge_alphas\"]:\n    for fold, (i_train, i_valid) in enumerate(folds, 1):\n        fold_train = train.iloc[i_train]\n        fold_valid = train.iloc[i_valid]\n        model = CoxModel(cfg[\"features\"], alpha=alpha).fit(fold_train)\n        loss = brier_ipcw(\n            fold_train.cvd_time, fold_train.cvd_event,\n            fold_valid.cvd_time, fold_valid.cvd_event,\n            model.predict_risk(fold_valid, cfg[\"horizon_years\"]),\n            cfg[\"horizon_years\"], cfg[\"min_censor_survival\"])\n        rows.append({\"alpha\": alpha, \"fold\": fold, \"IPCW_Brier\": loss})","language":"python","codeNote":"依据单元格3，配置为3折、seed=3407、5年时间窗。"},{"title":"用保存结果执行选择规则","paragraphs":["Brier分数越低，概率平方误差越小。按三个验证折的平均IPCW Brier排序，保存输出选择alpha=0.001，平均0.027901；alpha=0的平均为0.027904。差异只有约0.000003，保留预定规则的选择，同时承认优势很小。","折间结果还能揭示不稳定性：某一折中alpha=0.01并非处处更差，因此不能只取某一折的最好值。也不能在看见最终测试结果后改候选网格或指标，再把这次选择称为独立检验。"],"table":{"headers":["alpha","第1折","第2折","第3折","平均IPCW Brier"],"rows":[["0","0.027711","0.028256","0.027744","0.027904"],["0.001","0.027729","0.028251","0.027721","0.027901"],["0.01","0.027944","0.028313","0.027715","0.027991"]]},"code":"cv_results = pd.DataFrame(rows)\nmean_loss = cv_results.groupby(\"alpha\").IPCW_Brier.mean()\nmean_loss = mean_loss.sort_values(kind=\"stable\")\nselected_alpha = float(mean_loss.index[0])","language":"python","codeNote":"依据单元格4；表中是保存输出的六位小数，平均值按原始精度计算。"},{"title":"提交完整选择证据","paragraphs":["报告应包含数据模式、患者划分、折数、随机种子、候选alpha、每折分数与最终选择。若alpha=0在另一份预先规定的实验中获胜，应按规则记录。以展示惩罚效果为目的强制选择非零值，会改变评价问题。","岭模型的系数已经经过收缩，不能沿用普通Cox的未经调整P值和置信区间。项目仅为未惩罚模型输出常规推断列，惩罚模型保留系数与HR。选择完成后的重新拟合及独立评价要保持同一字段、预处理和时间窗，最终测试用于冻结流程后的评估。"],"note":"这些结果来自官方合成数据。低Brier值还受低事件率影响，应结合常数风险基线与后续校准分析理解。"}],"exercises":[{"prompt":"指出代码中保证折内重新拟合预处理的操作。","choices":[{"text":"先在全队列标准化一次","explanation":"它让验证和测试数据的分布提前进入训练。"},{"text":"每折创建CoxModel并对fold_train执行fit","explanation":"正确。CoxModel.fit在当前训练折重新拟合其FeatureEncoder。"},{"text":"只对cv_results按alpha分组","explanation":"汇总评价结果不会修复之前的预处理泄漏。"}],"correct":1},{"prompt":"根据保存的平均IPCW Brier选择alpha。","choices":[{"text":"0.001，并记录相对0的差异极小","explanation":"正确。0.027901为最小平均值，和0.027904的差异约0.000003。"},{"text":"0.01，因为惩罚越强越好","explanation":"惩罚强度不能单调保证性能；0.01的平均误差在表中最大。"},{"text":"查看最终测试后再决定","explanation":"这会使最终测试参与选择，失去独立评估作用。"}],"correct":0},{"prompt":"选择适用于岭Cox系数报告的做法。","choices":[{"text":"把普通Cox的P值复制到岭模型表","explanation":"收缩后的估计与普通Cox推断不同，这些P值没有对应保障。"},{"text":"把非零岭系数认定为已筛选出的因果变量","explanation":"纯L2通常不会把系数压到精确零，预测系数也不自动获得因果解释。"},{"text":"报告收缩系数与HR，另行说明推断限制","explanation":"正确。这与项目的惩罚模型输出范围一致。"}],"correct":2}],"takeaways":["预处理、模型和删失分布都要在当前训练折中拟合。","按平均IPCW Brier选择alpha，保留每折结果及差异大小。","惩罚强度由训练内验证确定，最终测试不得用于选参。"]},{"id":"w08","week":8,"part":"","title":"生存预测的区分度、误差与校准","summary":"在验证集上联合读取删失加权指标和分组 KM 校准，区分排序能力与概率准确性。","notebook":"w08_survival_evaluation.ipynb","kind":"practice","sections":[{"title":"先核对评价样本的五年状态","paragraphs":["本篇为独立运行预先固定普通Cox，alpha=0，使用完整指定字段在35,000人训练集拟合，在7,500人验证集评价。这里没有采用第七周选出的alpha=0.001，也没有报告最终测试表现。","验证集中整个观察期有302个事件，293个在五年内；4,180人在五年或之前删失，3,027人观察超过五年。按实现的时间边界，293+4,180+3,027=7,500。超过五年才发生事件的人属于五年时仍无事件且有观察支持的人群，不能提前标成五年病例。"],"table":{"headers":["五年评价状态","验证集人数"],"rows":[["五年内观察到事件","293"],["五年或之前删失","4,180"],["观察超过五年","3,027"],["合计","7,500"]]}},{"title":"读取排序指标的不同时间范围","paragraphs":["Harrell C比较可判断先后的一对人：较早发生事件者的预测危险是否更高。删失会让部分人员对无法比较。保存结果为0.875205。Uno型C把较早事件限制在五年内，并用训练删失分布修正权重，结果为0.873691。","五年累计/动态AUC比较五年内病例与观察超过五年的对照，经IPCW加权后为0.876690。C与AUC都主要衡量排序；同一批概率做严格单调变换后，排序可保持不变，但概率数值与校准会改变。不能只用较高C宣布风险估计准确。"],"code":"model = CoxModel(cfg[\"features\"], alpha=0.0).fit(train)\nh = cfg[\"horizon_years\"]\np_valid = model.predict_risk(valid, h)\nmetrics = evaluate_survival(\n    train, valid, p_valid, model.score(valid),\n    h, cfg[\"min_censor_survival\"])","language":"python","codeNote":"节选单元格3；项目score越高表示危险越高，与w06a调用的lifelines C接口符号约定不同。"},{"title":"用 IPCW 处理未知五年状态","paragraphs":["G(t)表示删失时间晚于t的概率，项目从训练集用反向KM估计。五年内观察到事件者的权重为1/G(T−)，观察超过五年者为1/G(5)。早期删失者的五年标签未知，在这个评价公式中的权重为0。","这种权重让有足够观察信息的人代表相似的未完整观察者，依赖独立删失及训练与评价删失机制可迁移等假设。若G太小，少量记录会获得巨大权重；配置阈值为0.05，时间支持不足时函数报错。真实资料中协变量相关失访可能需要条件删失模型。"],"formula":"wᵢ=1/G(Tᵢ−)，δᵢ=1且Tᵢ≤5；wᵢ=1/G(5)，Tᵢ>5；其余wᵢ=0","note":"事件时刻使用左极限G(T−)。Uno型C的人员对权重为1/G(T−)²，与Brier和AUC的单人权重不同。"},{"title":"解释概率误差与总体风险","paragraphs":["Brier把五年事件标签与预测概率之差平方，再按删失权重加权，最后除以全部评价人数7,500。不能删除早期删失后改用剩余人数作分母，也不能擅自除以权重总和。保存的IPCW Brier为0.027280，越低代表这个定义下的平均误差越小。","验证集平均预测风险为4.0549%，KM五年观察风险为4.0297%，点态95%区间为3.5992%至4.5106%。总体均值接近仍可能掩盖亚组或风险层级的偏差。低事件率也会让常数低风险预测取得较小Brier，评价时应另与适当的训练KM常数风险基线比较。"],"formula":"Brier_IPCW(5)=(1/n)×Σ wᵢ×(yᵢ−pᵢ)²；yᵢ=1表示五年内事件","note":"本notebook没有保存常数基线的对照数值；不能据0.027280单独声称优于该基线。"},{"title":"从训练边界构建校准图","paragraphs":["先对训练预测风险取五分位边界，再原样应用于验证集。每组横坐标是平均预测概率，纵坐标是组内1−KM(5)。点在对角线上方表示观察风险高于预测，点在下方表示预测偏高。横纵轴使用相同尺度，便于比较偏离程度。","最高风险组1,495人，五年内229个事件，平均预测15.9682%，KM风险15.7403%。最低风险组1,598人却只有3个事件，标为sparse_or_unsupported。即使点靠近对角线，稀疏组也难以给出精细结论；五组图只能提供粗略校准描述。"],"code":"edges = calibration_edges(\n    model.predict_risk(train, h), cfg[\"calibration_bins\"])\ncal = calibration_table(\n    valid.cvd_time, valid.cvd_event, p_valid, h, edges)","language":"python","codeNote":"节选单元格5；边界从训练预测得到，各组人数在验证集不必完全相等。","table":{"headers":["风险组","人数","五年内事件","平均预测","KM观察风险"],"rows":[["1","1,598","3","0.3139%","0.1877%"],["2","1,496","13","0.7055%","0.9230%"],["3","1,468","19","1.2118%","1.3204%"],["4","1,443","29","2.2200%","2.0934%"],["5","1,495","229","15.9682%","15.7403%"]]},"figure":{"file":"w08_survival_evaluation_cell5.png","alt":"官方7,500人验证集的五组KM校准图，边界由训练预测确定，竖线为组内观察风险区间。","caption":"官方7,500人验证集的五组KM校准图，边界由训练预测确定，竖线为组内观察风险区间。 源 Notebook 保存输出，第 6 个单元格。"}},{"title":"把不确定性放回对应对象","paragraphs":["校准图竖线是组内KM观察风险的点态95%区间。它不能作为模型C指数、Brier或个人风险的区间。发生0个事件或KM位于边界时，项目不会绘制虚假的零宽区间；事件少于5个、五年后支持人数少于20或无法估计时，会标记证据稀疏。","提交评价表和图时，标明验证集、五年时间窗、删失假设与指标方向，再分别描述排序、总体风险和分组校准。项目方法限于普通右删失，未实现竞争风险或性能bootstrap区间。普通ROC把全部cvd_event=0当对照，会误用早期删失资料。"]}],"exercises":[{"prompt":"将所有0<p<1的预测变为√p，判断排序和校准的变化。","choices":[{"text":"排序保持，预测普遍提高，校准和Brier可能改变","explanation":"正确。平方根严格单调且大于原概率，C与AUC排序可不变，绝对概率评价会受到影响。"},{"text":"排序一定反转","explanation":"平方根在0到1之间严格递增，不会反转顺序。"},{"text":"所有评价指标必定保持不变","explanation":"Brier和校准直接使用概率数值，不能只根据排序判断。"}],"correct":0},{"prompt":"在本验证集计算IPCW Brier时选择正确的分母。","choices":[{"text":"293个五年内事件","explanation":"只除以病例数不符合本项目Brier定义。"},{"text":"全部7,500人","explanation":"正确。早期删失者权重为0，但仍包含在原评价样本数n中。"},{"text":"有非零权重的3,320人","explanation":"简单删除早期删失并更换分母会得到另一个统计量。"}],"correct":1},{"prompt":"解释最低风险组被标记为证据稀疏的直接依据。","choices":[{"text":"这一组有1,598人，人数太多","explanation":"总体人数并不小；稳定性还取决于事件数和随访支持。"},{"text":"平均预测小于1%，模型必然错误","explanation":"低概率本身不说明模型错误。"},{"text":"五年内只有3个事件","explanation":"正确。项目对少于5个事件的组标记稀疏，点估计应结合区间谨慎读取。"}],"correct":2}],"takeaways":["C和AUC评价排序，Brier与校准还检查概率数值。","IPCW依赖删失与时间支持假设，早期删失者不能直接标为阴性。","校准分组边界来自训练集，图中区间只对应各组KM观察风险。"]},{"id":"w09","week":9,"part":"","title":"按患者组织三张病历表","summary":"识别一对多关系，先汇总记录，再用患者主键连接并验证人数。","notebook":"w09_relational_emr_and_sql.ipynb","kind":"practice","sections":[{"title":"从三张表的粒度开始","paragraphs":["Asset2 把同一批 50,000 名合成人员改写为病历形式。主表每人一行，诊断表每项诊断一行，测量表每项测量一行。Patient_ID 在主表中唯一，在另外两表中可以重复；后两表通过它关联主表。先说明一行代表的对象，再计算数量，才能避免把记录数当成人数。","保存输出中，诊断表的 4,417 行来自 4,271 人；测量表的 210,000 行覆盖全部 50,000 人。本课查看的是全队列表结构。后续建模使用固定的 35,000 人训练集和 7,500 人验证集，另有 7,500 人测试集封存。独立生成的 demo 数据只用于流程练习。"],"table":{"headers":["表","记录行数","唯一患者数","一行的含义"],"rows":[["master","50,000","50,000","一名患者"],["diseases","4,417","4,271","一项慢病记录"],["measurements","210,000","50,000","一项测量记录"]]}},{"title":"直接连接会放大记录数","paragraphs":["同一名患者若有 d 条诊断和 m 条测量，按 Patient_ID 直接连接两张明细表会得到 d × m 行。每条诊断与每条测量均组成一对。算术示例中，2 条诊断和 5 条测量产生 10 行，诊断计数被重复 5 次，测量计数被重复 2 次。","扩张后唯一患者数仍可能保持不变，均值、频数和模型权重却已经改变。没有诊断记录的人还可能被内连接排除。患者级分析应先分别把明细表聚合为每人一行，再以主表为左表连接。"],"formula":"某患者的明细连接行数 = 诊断记录数 d × 测量记录数 m"},{"title":"先聚合，再连接","paragraphs":["SQL 的两个公共表表达式分别按 Patient_ID 分组。COUNT(*) 统计记录行数。LEFT JOIN 保留主表中的每名患者；COALESCE 将找不到的记录计数写为 0。零条记录只描述当前表的覆盖情况，疾病状态还需要第 10 周的术语规则。","下面保留了项目 SQL 的核心步骤。使用内存 SQLite 可以复现连接，同时保持原始 CSV 不变。ORDER BY 只控制展示顺序，连接依据始终是患者标识。"],"code":"WITH disease_counts AS (\n    SELECT Patient_ID, COUNT(*) AS n_disease_records\n    FROM diseases GROUP BY Patient_ID\n), measurement_counts AS (\n    SELECT Patient_ID, COUNT(*) AS n_measurement_records\n    FROM measurements GROUP BY Patient_ID\n)\nSELECT p.Patient_ID, p.Age_At_2024,\n       COALESCE(d.n_disease_records, 0) AS n_disease_records,\n       COALESCE(m.n_measurement_records, 0) AS n_measurement_records\nFROM master AS p\nLEFT JOIN disease_counts AS d ON p.Patient_ID = d.Patient_ID\nLEFT JOIN measurement_counts AS m ON p.Patient_ID = m.Patient_ID\nORDER BY p.Patient_ID;","language":"sql","codeNote":"源文件 sql/01_patient_level_summary.sql；Notebook 第 4 格将三张表写入 SQLite 后执行。"},{"title":"连接检查需要覆盖三个方向","paragraphs":["行数检查能发现常见扩张，唯一性检查能发现同一患者重复出现，患者集合检查能发现有人丢失或被替换。三项检查分别覆盖不同错误。总行数相同仍可能同时发生重复与漏人，单看一项计数不足以验收。","连接前再检查主表 ID 唯一，以及每条诊断、测量记录的 ID 都能在主表找到。出现孤立 ID 时保留问题记录并核查来源，直接删除会掩盖数据覆盖错误。"],"code":"master = tables[\"master\"]\nassert master.Patient_ID.is_unique\nfor name in [\"diseases\", \"measurements\"]:\n    assert tables[name].Patient_ID.isin(master.Patient_ID).all()\nassert len(patient_summary) == len(master)\nassert patient_summary.Patient_ID.is_unique\nassert set(patient_summary.Patient_ID) == set(master.Patient_ID)","language":"python","codeNote":"前四项对应读取模块和 Notebook 的检查；最后一项显式核对患者集合。"},{"title":"把表结构转成可解释的特征","paragraphs":["记录计数可以用于质量审查，但不能直接解释为患病严重程度。下一课会把多种名称映射到 diabetes、CKD、AF，再生成每人每病一个 0/1 值；测量记录则需要统一名称、数值和单位后展开。","本版本的病历日期由合成规则生成，不能据此推断真实疾病发生顺序。Patient_ID、源行号和随访结局用于关联或评价，应从预测特征中排除。Asset1 与 Asset2 的交叉核对只能检验同批人员的转换过程。"]}],"exercises":[{"prompt":"计算一名患者有 3 条诊断、4 条测量时，两张明细表按患者 ID 直接连接的行数。","choices":[{"text":"12 行","explanation":"每条诊断匹配 4 条测量，共 3 × 4 = 12 行；这是连接算术示例。"},{"text":"7 行","explanation":"相加不能描述多对多匹配，每种诊断与测量组合都会形成一行。"},{"text":"1 行","explanation":"只有先把两表聚合到患者层，才会得到每人一行。"}],"correct":0},{"prompt":"选择能完整验收患者级连接的检查组合。","choices":[{"text":"行数、ID 唯一性、患者集合都与预期一致","explanation":"三项联合检查分别覆盖行数变化、重复患者和人员替换或遗漏。"},{"text":"只核对唯一患者数","explanation":"重复记录可能使总行数增大，但唯一患者数不变。"},{"text":"只核对结果总行数","explanation":"重复一人和遗漏另一人可能相互抵消，结果行数仍相同。"}],"correct":0},{"prompt":"解释诊断表中 4,417 行与 4,271 名患者的差异。","choices":[{"text":"部分患者有多条诊断记录","explanation":"记录是分析单元时可以重复患者；患者级分母应使用去重人数。"},{"text":"多出的 146 行都是错误重复","explanation":"同一患者记录不同慢病是合理情况，不能仅凭计数认定错误。"},{"text":"代表全队列只有 4,271 人","explanation":"主表覆盖 50,000 人，诊断表只覆盖有相应记录的人员。"}],"correct":0}],"takeaways":["每张表先写明一行代表的对象，再报告行数与唯一人数。","两张一对多明细表先分别聚合，再通过患者 ID 连接。","连接后同时核对行数、唯一性与患者集合。"]},{"id":"w10a","week":10,"part":"a","title":"逐步清洗名称、单位与缺失","summary":"通过名称映射、单位换算和来源核查，区分可恢复字段、舍入近似与不可恢复随访。","notebook":"w10a_emr_cleaning.ipynb","kind":"concept","sections":[{"title":"把术语映射写成可审查规则","paragraphs":["本课逐步处理官方全队列的三张 EMR 表。诊断表有 19 种写法，测量表有 35 种写法。先列出名称及频数，再将诊断归入 diabetes、CKD、AF，将测量归入 HbA1c、eGFR、SBP、BMI、Height、Weight。映射后必须检查未识别值，并逐行审查对应表。","High glucose 和 High blood sugar 在此版本的合成规则中映射为糖尿病，真实 EMR 中一次高血糖不足以建立该诊断。无诊断记录填 0 同样依赖当前生成机制。关键词匹配也有边界，含 sys 的文本可能同时涉及收缩压与舒张压，需人工核对。"]},{"title":"单位字段决定换算方式","paragraphs":["Description 中写有 HbA1c mmol/mol 的 1,531 条记录里，1,456 条的 Unit 实际为 %，只有 75 条为 mmol/mol。仅按名称换算会误改大量数值。全测量表共有 2,500 条 mmol/mol 记录，换算应以 Unit 为条件。","Value 转数值失败的 1,000 条全部是英尺英寸身高，应解析后换成厘米。5 英尺 7 英寸等于 170.18 cm；5 英尺 12 英寸等于 182.88 cm。转换失败记录需要解释，不能直接作为缺失丢弃。"],"formula":"HbA1c(%) = HbA1c(mmol/mol) ÷ 10.929 + 2.15；身高(cm) = (英尺 × 12 + 英寸) × 2.54","code":"is_ifcc = (measures[\"measure\"] == \"HbA1c\") & (measures[\"Unit\"] == \"mmol/mol\")\nmeasures.loc[is_ifcc, \"value_num\"] = measures.loc[is_ifcc, \"value_num\"] / 10.929 + 2.15\nmeasures.loc[is_ifcc, \"Unit\"] = \"%\"\nassert measures[\"value_num\"].notna().all()","language":"python","codeNote":"节选并补充转换完成检查；先完成第 29–31 格的身高解析，再执行。"},{"title":"展开测量，并保留 BMI 来源","paragraphs":["当前版本没有重复的患者—测量组合，可以转成每人一行的宽表。40,000 人直接记录 BMI，10,000 人只记录身高体重。后者可按定义计算 BMI，并保留 BMI_source。身高体重必须来自该患者的同一份 EMR，不能从 Asset1 回填。","BMI 直接记录组的平均绝对误差为 0.002488，派生组为 0.032899 kg/m²；派生组最大误差 0.630001。身高体重舍入会沿平方和除法传播。真实重复测量还需先规定基线前的时间窗、排序和同日取值规则。"],"formula":"BMI(kg/m²) = 体重(kg) ÷ [身高(cm) ÷ 100]²","code":"bmi_calc = meas_wide[\"Weight\"] / (meas_wide[\"Height\"] / 100) ** 2\nmeas_wide[\"BMI_source\"] = np.where(\n    meas_wide[\"BMI\"].notna(), \"recorded\", \"derived_from_height_weight\")\nmeas_wide[\"BMI\"] = meas_wide[\"BMI\"].fillna(bmi_calc)","language":"python","codeNote":"根据第 42 格改写来源标签，适用于当前身高体重齐全的官方版本；不完整输入用 W10b 的 unavailable 标签。"},{"title":"分别记录缺失处理与年龄规则","paragraphs":["主表中 5,727 人缺少吸烟状态，教程保留为 unknown。与 Asset1 对照后可见，这些人原本都属于 non；这个结论来自已知合成数据，不能据此把其他数据中的全部缺失统一填成从不吸烟。增加未知类别仍是一项建模选择，不会自动消除缺失偏差。","Age_At_2024 减 7 是本版本回到 2017 年基线的生成规则，年龄舍入误差小于 0.005 岁。真实研究应从可核查的出生信息和基线日期定义年龄，并记录精度。"]},{"title":"量化随访信息丢失","paragraphs":["事件日期只保留月份，取月中会产生日期近似误差。更严重的是，47,991 名删失者的记录月份统一为 2022-12，各自真实停止观察的时间已经丢失。任何确定性换算都无法从这个共同月份恢复个人连续随访时间。","教程故意构造月中时间作为反例。相对 Asset1，删失者平均高估 1.051268 年，事件者平均误差 −0.003233 年。延长风险集中的无事件时间会影响基线危险和绝对风险。工程重建只输出带有 NOT_original 标记的粗化时间。"],"table":{"headers":["人群","人数","重建时间减原始时间：均值","有符号误差范围"],"rows":[["删失者","47,991","+1.051268 年","−1.355126 至 +3.274299 年"],["事件者","2,009","−0.003233 年","−0.046537 至 +0.038292 年"]]},"figure":{"file":"w10a_followup_time_error.png","alt":"事件者与删失者的随访重建误差分布，删失者呈明显正偏差","caption":"官方全队列的随访重建误差。左：2,009 名事件者，单位为天。右：47,991 名删失者，单位为年。月中近似令删失者平均高估 1.051268 年；图像来自源 Notebook 保存输出，未重新拟合。"}},{"title":"核对字段与核对模型分开完成","paragraphs":["合并时以主表左连接，并检查每人一行。与 Asset1 比较前须确认本版本的公开患者映射；换了版本或排序后，不能依赖位置盲目对齐。先逐字段比较误差，再解释模型变化。","在各自的完整 50,000 人数据上拟合并计算，Asset1 与月中近似 EMR 的表观 C 指数分别为 0.876 和 0.875，HR 也较接近。这些 C 值使用了拟合模型的同一批人员。排序相近不能证明绝对风险正确，更不能恢复丢失的信息。这是同一合成队列的转换检查，未提供独立人群中的泛化证据。"]}],"exercises":[{"prompt":"选择 HbA1c 名称含 mmol/mol、Unit 为 % 时的处理。","choices":[{"text":"保留当前数值，并按单位审查分布","explanation":"当前版本以 Unit 列识别换算对象；名称与单位不一致也应计入审查。"},{"text":"再除以 10.929 并加 2.15","explanation":"该值已经按百分比记录，再换算会产生错误。"},{"text":"删除整名患者","explanation":"名称与单位不一致需核查，当前版本已有确定规则，无需直接删人。"}],"correct":0},{"prompt":"计算 72 kg、身高 180 cm 对应的 BMI，结果保留两位小数。","choices":[{"text":"22.22 kg/m²","explanation":"180 cm = 1.80 m，72 ÷ 1.80² = 22.22；这是公式练习，并非新增观察结果。"},{"text":"0.0022 kg/m²","explanation":"该结果将厘米直接代入，漏掉了转换为米的步骤。"},{"text":"40.00 kg/m²","explanation":"BMI 的分母是身高的平方，单次除以身高不符合定义。"}],"correct":0},{"prompt":"解释统一删失月份对个人随访时间的限制。","choices":[{"text":"个人停止观察时间已经丢失，只能另行定义近似并评估偏差","explanation":"同一个输出月份对应许多可能的原始时点，无法唯一逆推出个人时间。"},{"text":"把月份统一取 15 日就能恢复精确随访","explanation":"月中只给出一个约定点，无法恢复被统一覆盖的个人删失时点。"},{"text":"C 指数相近说明日期已恢复","explanation":"排序指标对部分时间错误可能不敏感，无法证明个体日期或绝对风险正确。"}],"correct":0}],"takeaways":["名称标准化、数值解析和单位换算分别审查。","BMI 保留记录或派生来源，舍入误差需要量化。","统一删失月份丢失了个人时间，模型排序接近不能弥补。"]},{"id":"w10b","week":10,"part":"b","title":"把清洗规则做成可核查重建器","summary":"用程序护栏、审查记录和误差表验证重建，并明确保留不可恢复的信息。","notebook":"w10b_reconstruction.ipynb","kind":"practice","sections":[{"title":"一次重建交付三类结果","paragraphs":["工程篇调用 reconstruct，返回患者宽表 rec、审查汇总 audit 和标准化测量明细 standardized_measurements。宽表用于检查患者级变量，汇总记录转换范围，明细保留原始 Description、Value、Unit 与新生成的 canonical_measure、standard_value，方便追溯每个数值。","保存输出覆盖官方 50,000 人、4,417 条诊断和 210,000 条测量。2,500 条 HbA1c 需要 mmol/mol 换算，1,000 条身高采用英尺英寸，40,000 条 BMI 的 Unit 为空。空单位的处理在当前版本有明确规则，并写入审查计数。"],"code":"from primecvd.data import load_emr\nfrom primecvd.reconstruction import reconstruct, compare_to_clean\nrec, audit, standardized_measurements = reconstruct(load_emr(cfg))\ndisplay(pd.Series(audit))\ndisplay(compare_to_clean(rec, df))","language":"python","codeNote":"源 Notebook 第 3 格。cfg 和 df 由该 Notebook 的官方数据初始化步骤生成。"},{"title":"对未知输入及时停止","paragraphs":["读取阶段检查主表 ID 唯一及外键完整。重建阶段检查诊断词典、测量名称、单位、吸烟编码和数值有效性。同一患者出现重复同类测量时程序报错，要求先定义聚合窗口。直接取均值或最后一条会把研究规则藏在数据处理步骤中。","下面的练习只修改内存副本，把一条单位改成未知值。预期结果是 ValueError。观察报错信息能定位是哪种测量、哪个单位需要审查；原始 CSV 保持完整。"],"code":"tables = load_emr(cfg)\nchanged = {name: table.copy(deep=True) for name, table in tables.items()}\nidx = changed[\"measurements\"].index[0]\nchanged[\"measurements\"].loc[idx, \"Unit\"] = \"unknown_unit\"\ntry:\n    reconstruct(changed)\nexcept ValueError as exc:\n    print(type(exc).__name__, str(exc))\nelse:\n    raise AssertionError(\"未知单位未触发审查\")","language":"python","codeNote":"落实第 7 格独立练习；异常处理行为见 primecvd/reconstruction.py。"},{"title":"让 BMI 每个值都有来源","paragraphs":["重建器优先保留直接记录的 BMI；只有 BMI 缺失且同一 EMR 中有身高体重时才派生。BMI_source 分别记为 recorded、derived_from_height_weight 或 unavailable。缺一项测量时应保留不可得状态，不能借助 Asset1 补齐后再报告为独立重建。","当前官方输出为 40,000 个 recorded 和 10,000 个 derived_from_height_weight，BMI 缺失比例为 0。这个结果由当前文件支持。处理更早版本或不完整输入时，仍应实际统计来源和缺失，不能预先假定完整。"],"formula":"派生 BMI = Weight ÷ (Height ÷ 100)²"},{"title":"误差表包含精度与覆盖范围","paragraphs":["compare_to_clean 先按患者 ID 一对一合并，核对人员集合、IRSD、结局与年龄映射，再比较可恢复字段。每个变量同时报告可比人数、不可得人数、平均绝对误差、最大误差和容差内比例。均值接近零仍可能掩盖个别人较大的误差。","年龄平均绝对误差约 0.002478 岁；BMI 约 0.008570 kg/m²，最大约 0.630001。BMI 在 0.011 容差内的比例为 89.644%。HbA1c 误差接近机器精度，eGFR、SBP 及诊断完全一致。容差是本项目核查设定，不能直接当作临床可接受界限。"],"formula":"MAE = Σ|重建值 − 原值| ÷ 可比人数","table":{"headers":["字段","可比人数","平均绝对误差","最大绝对误差","容差内比例"],"rows":[["Age","50,000","0.002478 岁","0.005 岁以内","100%"],["BMI","50,000","0.008570 kg/m²","0.630001 kg/m²","89.644%"],["HbA1c","50,000","约 0","约 0","100%"],["eGFR、SBP","各 50,000","0","0","100%"]]}},{"title":"对无法恢复的时间使用明确边界","paragraphs":["输出保留 CVD_Time_month_recorded，并提供名称带 NOT_original 的粗化时间用于观察；不生成可被误当成原始随访的 cvd_time。月级日期损失日级精度，统一删失月份还损失个人观察终点，后者不可逆。主生存模型继续使用 Asset1 的原始连续随访。","同一合成队列中的字段一致性支持清洗规则核查，无法提供外部人群的预测表现。验收时将准确恢复、带舍入误差恢复、无法恢复三类字段分别列清，并附程序停止条件和原始数据来源。"]}],"exercises":[{"prompt":"选择某人只有体重、没有身高且未记录 BMI 时的处理。","choices":[{"text":"保留 BMI 缺失，BMI_source 标为 unavailable","explanation":"公式所需输入不足；来源标签需要准确表达不可得状态。"},{"text":"从 Asset1 补入并标为重建","explanation":"这会掺入核查答案，破坏重建过程的可追溯性。"},{"text":"用总体平均身高计算并标为 recorded","explanation":"该值包含新增插补假设，且 recorded 标签与事实不符。"}],"correct":0},{"prompt":"解释 BMI 平均误差很小但最大误差为 0.63 的含义。","choices":[{"text":"总体平均掩盖了部分派生记录的较大舍入误差","explanation":"均值与最大值描述不同方面，还应按来源分层核查误差。"},{"text":"所有 BMI 都有 0.63 的误差","explanation":"最大值只描述最极端记录，不能替代误差分布。"},{"text":"单位换算一定全部错误","explanation":"来源中的舍入也可产生误差，需要结合来源及明细定位。"}],"correct":0},{"prompt":"选择重复患者—测量组合出现时的工程处理。","choices":[{"text":"暂停并明确时间窗与聚合规则","explanation":"当前重建器拒绝静默聚合，避免随数据版本变化而悄悄改变特征定义。"},{"text":"默认保留文件最后一行","explanation":"文件顺序未必代表临床时间，也未保证该记录早于预测起点。"},{"text":"直接把重复测量当作两名患者","explanation":"患者 ID 对应同一人，重复拆分会破坏患者级结构。"}],"correct":0}],"takeaways":["重建结果同时交付患者表、审查汇总和标准化明细。","未知单位、未知术语和重复测量应触发明确审查。","逐字段报告来源与误差，精确个人随访保持不可恢复标记。"]},{"id":"w11","week":11,"part":"","title":"比较亚组与单位错误的影响","summary":"固定模型和验证人员，联合检查亚组信息量、校准与受控单位错误造成的变化。","notebook":"w11_subgroups_and_sensitivity.ipynb","kind":"practice","sections":[{"title":"先固定人员与模型","paragraphs":["本课以官方 Asset1 的 35,000 名训练人员拟合普通 Cox 模型，alpha = 0，再在固定的 7,500 名验证人员中查看年龄和 IRSD 亚组。年龄亚组互斥，IRSD 亚组也互斥；两套分组描述同一验证集，不应将全部亚组人数再相加。","评价时间为 5 年。验证集共观察到 302 个事件，其中 293 个在 5 年内发生；4,180 人在 5 年内无事件删失，3,027 人随访超过 5 年。计算 5 年结局时，早期删失者的状态未知，不能直接归为未发生事件。"],"code":"from primecvd.survival import CoxModel\nfrom primecvd.pipeline import subgroup_table\nmodel = CoxModel(cfg[\"features\"], alpha=0.0).fit(train)\nresult = subgroup_table(train, valid, model, cfg)\ndisplay(result)","language":"python","codeNote":"源 Notebook 第 3 格；以下数值属于这份普通 Cox 练习，不混用其他流水线中被 CV 选中的模型。"},{"title":"先看每组的信息量","paragraphs":["18–39 岁组有 1,707 人，却只有 10 个观察事件。60 岁及以上组有 1,503 人、197 个事件。样本量相近不代表风险估计精度相近，还要查看事件数、早期删失和 5 年后的在险人数。","项目代码在人数少于 50、观察事件少于 5，或 5 年后在险人数少于 20 时，仅标记稀疏状态，不输出整套指标。这是防止低信息量结果被过度解读的工程阈值，不能保证通过阈值后估计就足够稳定。"],"table":{"headers":["验证集年龄组","人数","全部观察事件","5 年内事件","5 年内删失","5 年后在险"],"rows":[["18–39 岁","1,707","10","10","988","709"],["40–59 岁","4,290","95","91","2,439","1,760"],["60 岁及以上","1,503","197","192","753","558"]]}},{"title":"把风险水平、校准与排序分开读","paragraphs":["18–39 岁组平均预测风险为 0.526%，KM 估计为 0.592%，KM 95% 区间为 0.319%–1.097%；60 岁及以上组分别为 12.790%、13.214%，区间为 11.560%–15.083%。这些都是该亚组的 5 年风险。","C 指数比较可比患者对的风险排序，平均预测风险与 KM 风险比较总体水平。亚组变量范围和风险分布更窄时，排序任务本身也会改变。单个较低 C 值不足以证明模型对该组不公平；本练习未提供性能差异的区间或正式检验。"]},{"title":"用受控替换隔离单位错误","paragraphs":["重建器分别运行正确换算和故意漏换算两个版本，然后仅按 Patient_ID 替换验证集的 HbA1c。患者、其他预测变量、随访结局、模型和评价时间全部固定。原始文件不变，模型也不重新拟合。这样的比较可把变化定位到这项数据质量错误。","两种情景的 KM 风险均为 4.030%，平均预测风险却从 4.055% 升到 8.224%。漏换算使部分 mmol/mol 数值直接进入原本按 % 训练的模型，推高预测风险。Harrell C 同时从 0.8752 降到 0.8427，IPCW Brier 从 0.02728 升到 0.06424。"],"table":{"headers":["指标","正确换算","遗漏换算"],"rows":[["验证人数","7,500","7,500"],["平均预测 5 年风险","4.0549%","8.2236%"],["KM 5 年风险","4.0297%","4.0297%"],["Harrell C","0.875205","0.842685"],["5 年 IPCW AUC","0.876690","0.844863"],["5 年 IPCW Brier","0.02728","0.06424"]]}},{"title":"解释敏感性结果的范围","paragraphs":["Brier 是删失加权的预测平方误差，越小越好；C 与 AUC 衡量排序，越大通常越好。某种错误可以显著改变概率而较少改变排序，因此需要联合检查。本次实验中多项指标均变差，不应推断所有数据错误都会让每项指标同向变化。","IPCW 的删失分布由训练集估计，需要独立删失及足够随访支持。亚组来自同一合成队列，Asset2 也代表同一批人。该实验可以解释单位遗漏对既定模型的影响，不能建立外部有效性、因果结论或临床可部署性。"],"formula":"Brier_IPCW(5) = Σ wᵢ(5) × [yᵢ(5) − pᵢ(5)]² ÷ n；早期删失者权重为 0"}],"exercises":[{"prompt":"选择单位敏感性实验中被改变的对象。","choices":[{"text":"同一验证人员的 HbA1c 换算结果","explanation":"模型、其他特征、人员与结局固定，因此能隔离该字段的单位错误。"},{"text":"验证集患者与模型系数都改变","explanation":"同时改变多人群和模型会引入额外差异，无法只归因于单位错误。"},{"text":"用 Asset2 替换为一个独立外部人群","explanation":"Asset2 来自同一批合成人员，并未引入外部队列。"}],"correct":0},{"prompt":"解释两种单位情景中 KM 风险完全相同的原因。","choices":[{"text":"观察时间和结局没有改变","explanation":"KM 只由验证集观察时间和事件决定，替换 HbA1c 不改变这些输入。"},{"text":"两种情景的预测概率相同","explanation":"保存输出中平均预测风险从约 4.05% 升到 8.22%。"},{"text":"KM 能自动纠正错误单位","explanation":"KM 不使用 HbA1c，无法替模型修正输入单位。"}],"correct":0},{"prompt":"比较 18–39 岁组的 1,707 人与 10 个事件，选择最稳妥的报告方式。","choices":[{"text":"同时报告人数、事件数、删失与风险区间，并标明探索性","explanation":"事件稀少会限制信息量，完整分母与区间比单个指标更能表达不确定性。"},{"text":"样本超过 1,000 即可忽略不确定性","explanation":"生存结果的信息量与事件及随访有关，人数本身不足以保证精度。"},{"text":"只报告最显著的亚组结果","explanation":"筛选结果会掩盖不确定性与多重比较，不能完整表达既定亚组分析。"}],"correct":0}],"takeaways":["亚组评价先交代人数、事件数与随访支持。","固定人员、模型和其他字段，才能清楚解释单位错误实验。","同时看排序和绝对风险；同队列探索不能替代外部验证。"]},{"id":"w12","week":12,"part":"","title":"冻结方案，完成一次最终评价","summary":"用来源与文件哈希固定分析方案，完成独立测试评价并交付可复现报告。","notebook":"w12_capstone.ipynb","kind":"practice","sections":[{"title":"在最终评价前写完方法","paragraphs":["结项任务把前面的学习步骤合成一条可复现流程：确认数据来源，固定患者划分，在训练集内选择惩罚强度，报告验证集表现，完成 EMR 重建核查，最后才评价冻结模型。方法记录应先写明结局、基线、5 年预测窗、变量单位、参考组、缺失处理与删失假设。","官方数据共 50,000 人，训练、验证、测试分别为 35,000、7,500、7,500 人。工程流程的模型选择只用训练集内三折 CV，最终模型也只在训练集拟合。教程中展示全队列概念计算的数字，需与独立验证或测试性能分开标注。"]},{"title":"完整运行不会自动解锁测试","paragraphs":["Notebook 使用独立输出目录 notebook_capstone_official，避免覆盖每周练习。run_all 完成训练内 CV、验证评价和重建报告，生成 report.html 与 frozen_spec.json。官方保存输出选中 alpha = 0.001，选择规则是训练内平均 5 年 IPCW Brier 最小。","保存的逐折 Brier 显示 alpha = 0 与 0.001 表现十分接近。选中某值只说明它按预定规则略占优，不能据此宣称惩罚带来明显改善。不要用验证结果再挑一个更好看的模型。"],"code":"from primecvd.pipeline import run_all\ncfg[\"output_dir\"] = f\"outputs/notebook_capstone_{MODE}\"\nreport_path = run_all(cfg)\nfrozen_path = report_path.parent / \"frozen_spec.json\"\nfrozen = json.loads(frozen_path.read_text(encoding=\"utf-8\"))\ndisplay(frozen)","language":"python","codeNote":"源 Notebook 第 3 格；本课程引用该格已有官方保存结果，未替学习者解锁测试集。"},{"title":"冻结的不仅是一个模型名","paragraphs":["冻结文件记录配置、数据、患者划分、模型与校准边界的 SHA-256，还保存选择规则、最终拟合集与测试状态。最终测试前程序重新计算这些哈希，只要其中一项变化就阻止评价。这能发现换数据、换分组、换模型或调整校准分箱等变动。","校准分界由训练风险分布确定，不能看过测试集后重新分箱改善外观。随机种子、来源版本、软件环境和运行命令同样应写入报告。哈希验证文件一致性，统计合理性仍需逐项检查。"],"table":{"headers":["冻结记录","该保存输出的状态"],"rows":[["selected_alpha","0.001"],["selection_rule","训练集内部三折 CV 的平均 5 年 IPCW Brier 最小"],["final_fit_set","仅训练集 70%，未用 train+valid 重拟合"],["test_opened","False"],["完整性检查","配置、数据、划分、模型、校准边界五类 SHA-256"]]}},{"title":"完成后显式评价一次","paragraphs":["源 Notebook 的 finalize 调用保持注释，仓库没有提供最终测试性能。学习者完成方法冻结后才可执行解锁命令。finalize 加载已保存模型，在测试人员中计算指标与校准，写出 test_evaluation.json；同一目录随后禁止重训和再次测试。","已经查看测试结果后，改目录或换随机种子不会让这些观察重新变成未见数据。若依据测试结果调整方案，应如实记录使用历史，并为改后模型寻找新的独立评价数据。当前报告的性能指标仅有点估计，尚未计算 bootstrap 区间。"],"code":"# 先核对冻结方案与方法记录。\n# 仅在准备完成后执行以下两行：\n# from primecvd.pipeline import finalize\n# finalize(cfg, unlock_test=True)","language":"python","codeNote":"源 Notebook 第 5 格保留为注释。命令行对应 python run.py finalize --unlock-test，需使用与冻结输出一致的配置。"},{"title":"交付可检查的报告与运行记录","paragraphs":["按仓库模板写 3–5 页报告，包含研究目标、文件版本与哈希、患者划分、普通及惩罚 Cox、评价假设、主要图表、重建误差和一项具体错误实验。每张图注明人群、单位、时间窗与分母，每个数值链接到实际生成输出。测试尚未运行时如实标明。","局限至少交代合成机制、删失与比例风险假设、稀少亚组、尚未完成的诊断或区间估计、EMR 个人随访丢失及临床不可部署性。Asset2 的重建核对不能替代外部验证。记录实际运行的平台、测试通过与跳过情况，其他平台的结果不能凭环境文件推定。"],"code":"python run.py doctor\npython run.py all\npython -m pytest -q\npython scripts/execute_notebooks.py","language":"bash","codeNote":"在项目根目录执行并记录真实输出；all 默认使用官方配置，执行前应已有核验通过的官方源文件。"}],"exercises":[{"prompt":"选择仓库 W12 保存输出已经支持的结论。","choices":[{"text":"训练内 CV 选中 alpha = 0.001，测试尚未打开","explanation":"冻结文件明确记录 selected_alpha = 0.001 与 test_opened = False，finalize 保持注释。"},{"text":"最终测试集 C 指数已经达到 0.875","explanation":"0.875 出现在相关验证结果中，仓库未提供最终测试性能。"},{"text":"最终模型已经在训练加验证人员上重拟合","explanation":"冻结记录明确写明最终拟合集仅为训练集 70%。"}],"correct":0},{"prompt":"选择发现冻结后校准分界文件被改动时的处理。","choices":[{"text":"停止测试并核查变动，按真实使用历史修正记录","explanation":"校准边界属于冻结方案的一部分，哈希不一致需要说明原因，不能绕过检查。"},{"text":"手动修改冻结哈希以便通过","explanation":"这样会破坏完整性检查，掩盖分析方案已改变的事实。"},{"text":"只要模型系数相同就继续","explanation":"测试的分析方案还包括数据、划分、配置和校准边界。"}],"correct":0},{"prompt":"说明查看测试结果后再次调整模型的报告要求。","choices":[{"text":"记录测试已参与方案调整，并另寻独立评价数据","explanation":"已见结果会影响后续决策，换目录无法消除这一使用历史。"},{"text":"换一个输出目录即可重新宣称独立测试","explanation":"文件位置改变不会改变研究者已查看结果的事实。"},{"text":"只留下表现最好的一次结果","explanation":"隐去选择过程会使性能估计过于乐观，并损害可复现性。"}],"correct":0}],"takeaways":["模型、数据划分、配置与校准边界一起冻结。","训练内选择、验证报告、最终测试各有明确用途。","只报告实际运行结果，保留测试使用历史与复现证据。"]}];